# V7.79 TRUE LAZY NAVIGATION -------------------------------------------------
# Normal tab/page navigation must never perform live network work.  Fantasy Edge
# renders from the last certified weekly snapshot (persisted in state) or from
# the packaged local board immediately.  Live feeds are rebuilt only when the
# user explicitly requests a refresh.
import zlib as _v778_zlib, base64 as _v778_base64

def _v778_snapshot_encode(df):
    """V8.07 fast binary snapshot. Pickle+zlib avoids multi-minute JSON decode on Cloud."""
    try:
        import pickle as _v807_pickle
        raw=_v807_pickle.dumps(df,protocol=_v807_pickle.HIGHEST_PROTOCOL)
        packed=_v778_zlib.compress(raw,3)
        return "P1:"+_v778_base64.b64encode(packed).decode("ascii")
    except Exception:
        return ""

def _v778_snapshot_decode(blob):
    """Decode only the fast V8.07+ snapshot format during startup.

    Legacy JSON snapshots are deliberately skipped instead of blocking the app for
    minutes. One explicit weekly refresh migrates them to P1 automatically.
    """
    try:
        if not blob:
            return pd.DataFrame()
        text=str(blob)
        if not text.startswith("P1:"):
            st.session_state["_v807_legacy_snapshot_skipped"]=True
            return pd.DataFrame()
        import pickle as _v807_pickle
        packed=_v778_base64.b64decode(text[3:].encode("ascii"))
        raw=_v778_zlib.decompress(packed)
        out=_v807_pickle.loads(raw)
        return out if isinstance(out,pd.DataFrame) else pd.DataFrame()
    except Exception as _v807_snapshot_error:
        st.session_state["_v807_snapshot_decode_error"]=f"{type(_v807_snapshot_error).__name__}: {_v807_snapshot_error}"
        return pd.DataFrame()


def _v809_snapshot_file_save(df):
    """Persist the large weekly board outside JSON/cloud state.

    The old architecture embedded a base64-compressed DataFrame inside the league
    state and then JSON-serialized/uploaded that giant payload twice per refresh.
    On Streamlit Cloud this could spend minutes on the final "saving player board"
    step.  Keep the board in a compact local binary file + session cache instead;
    league state stores only small metadata/team maps.
    """
    try:
        import pickle as _v809_pickle
        raw=_v809_pickle.dumps(df,protocol=_v809_pickle.HIGHEST_PROTOCOL)
        packed=_v778_zlib.compress(raw,1)
        tmp=_V809_WEEKLY_SNAPSHOT_FILE.with_suffix('.tmp')
        tmp.write_bytes(packed)
        tmp.replace(_V809_WEEKLY_SNAPSHOT_FILE)
        st.session_state['_v809_weekly_board']=df.copy()
        return True
    except Exception as e:
        st.session_state['_v809_snapshot_write_error']=f"{type(e).__name__}: {e}"
        return False

def _v809_snapshot_file_load():
    try:
        cached=st.session_state.get('_v809_weekly_board')
        if isinstance(cached,pd.DataFrame) and len(cached):
            return cached.copy()
        if not _V809_WEEKLY_SNAPSHOT_FILE.exists():
            return pd.DataFrame()
        import pickle as _v809_pickle
        raw=_v778_zlib.decompress(_V809_WEEKLY_SNAPSHOT_FILE.read_bytes())
        out=_v809_pickle.loads(raw)
        if isinstance(out,pd.DataFrame) and len(out):
            st.session_state['_v809_weekly_board']=out.copy()
            return out
    except Exception as e:
        st.session_state['_v809_snapshot_read_error']=f"{type(e).__name__}: {e}"
    return pd.DataFrame()

def _v809_persist_refresh_state_fast(s):
    """Save refresh metadata locally without blocking on cloud round-trips.

    Cloud sync remains available from League Setup, but a weekly NFL refresh must
    never wait on a multi-megabyte state upload/probe before returning control.
    """
    try:
        slim=dict(s)
        slim.pop('_weekly_board_snapshot_gz',None)
        STATE.write_text(json.dumps(slim,indent=2))
        st.session_state['_v794_runtime_state']=dict(slim)
        return True
    except Exception as e:
        st.session_state['_v809_state_write_error']=f"{type(e).__name__}: {e}"
        return False

def _v809_decision_mask(df,state_snapshot):
    """Rows that need expensive canonical refresh math.

    V8.11: refresh is a *data ingestion* operation, not a reason to run deep row-wise
    decision math for hundreds of league/directory rows.  Deep intelligence is limited
    to the user's roster plus the strongest current fantasy candidates.  Waiver finalists,
    trade targets, etc. are enriched on their own page when actually needed.
    """
    if df is None or df.empty:
        return pd.Series(False,index=getattr(df,'index',[]))
    idx=df.index
    proj=pd.to_numeric(df.get('projection',pd.Series(index=idx,dtype=float)),errors='coerce').fillna(0)
    ext=pd.to_numeric(df.get('_external_week_projection',pd.Series(index=idx,dtype=float)),errors='coerce').fillna(0)
    mr=pd.to_numeric(df.get('market_pick',df.get('consensus_rank',pd.Series(index=idx,dtype=float))),errors='coerce').fillna(9999)
    model=pd.to_numeric(df.get('model_rank',pd.Series(index=idx,dtype=float)),errors='coerce').fillna(9999)
    pos=df.get('position',pd.Series('',index=idx)).fillna('').astype(str).str.upper()
    keys=df.get('player',pd.Series('',index=idx)).astype(str).map(_owner_key)

    my_keys=set()
    try:
        own=(state_snapshot or {}).get('ownership',{}) or {}
        my_keys={str(k) for k,v in own.items() if isinstance(v,dict) and str(v.get('owner','FA'))=='1'}
    except Exception:
        pass
    my_mask=keys.isin(my_keys)

    fantasy=pos.isin(['QB','RB','WR','TE','K','DL','DB'])
    relevant=fantasy & ((proj>0) | (ext>0) | (mr<=350) | (model<=350))
    score=pd.DataFrame({'mr':mr,'model':model,'proj':proj,'ext':ext},index=idx)
    cand=score[relevant].sort_values(['mr','model','ext','proj'],ascending=[True,True,False,False]).head(220).index
    mask=pd.Series(False,index=idx)
    mask.loc[cand]=True
    mask=mask | my_mask
    return mask & fantasy


def _v789_apply_saved_team_map(df, state_snapshot):
    """Restore verified NFL team identity from the last certified weekly refresh."""
    if df is None or df.empty:
        return df
    out=df.copy()
    team_map=dict((state_snapshot or {}).get("_weekly_team_map",{}) or {})
    if not team_map:
        return out
    if "_live_team_verified" not in out.columns:
        out["_live_team_verified"]=0
    for idx,r in out.iterrows():
        k=norm(r.get("player",""))
        t=str(team_map.get(k,"") or "").upper().strip()
        if not t or t in {"NFL","FA","NONE","N/A"}:
            continue
        cur=str(r.get("team","") or "").upper().strip()
        verified=float(pd.to_numeric(pd.Series([r.get("_live_team_verified",0)]),errors="coerce").fillna(0).iloc[0])
        if verified<=0 or cur in {"","NFL","FA","NONE","N/A"}:
            out.at[idx,"team"]=t
            out.at[idx,"_live_team_verified"]=1
    return out


def _v792_apply_raw_sleeper_truth(board_df, players_dict):
    """Attach current team + availability identity directly from Sleeper's raw NFL directory.

    Unlike the ranked active-roster directory, this intentionally keeps reserve/PUP/IR
    players because they still have an NFL team and their status is decision-relevant.
    It never changes projections, VORP, ownership, or market value.
    """
    if board_df is None or not isinstance(board_df,pd.DataFrame) or board_df.empty:
        return board_df
    if not isinstance(players_dict,dict) or not players_dict:
        return board_df
    out=board_df.copy()
    truth={}
    for _pid,_pl in players_dict.items():
        if not isinstance(_pl,dict):
            continue
        _name=_pl.get("full_name") or " ".join([str(_pl.get("first_name") or ""),str(_pl.get("last_name") or "")]).strip()
        if not _name:
            continue
        _team=str(_pl.get("team") or "").upper().strip()
        _status=_v677_normalize_injury_status(_pl.get("injury_status") or "")
        truth[_owner_key(_name)]={"team":_team,"status":_status,"active":_pl.get("active"),"pid":str(_pid)}
    if not truth:
        return out
    if "_live_team_verified" not in out.columns:
        out["_live_team_verified"]=0
    hard={"OUT","IR","PUP","NFI","SUSPENDED","DO NOT DRAFT"}
    for _idx,_r in out.iterrows():
        _t=truth.get(_owner_key(_r.get("player","")))
        if not _t:
            continue
        _team=str(_t.get("team") or "").upper().strip()
        if _team and _team not in {"NFL","FA","NONE","N/A"}:
            out.at[_idx,"team"]=_team
            out.at[_idx,"_live_team_verified"]=1
        _raw=_v677_normalize_injury_status(_t.get("status",""))
        _existing=_v677_normalize_injury_status(_r.get("injury_effective",_r.get("injury","")))
        if _raw in hard:
            out.at[_idx,"injury_effective"]=_raw
            out.at[_idx,"injury"]=_raw
            out.at[_idx,"injury_source"]="Sleeper live roster status"
            out.at[_idx,"injury_status_verified"]=True
            out.at[_idx,"injury_decision_unresolved"]=False
        elif _existing not in hard:
            # Healthy/undesignated roster entries establish a live availability baseline
            # without erasing a stronger official weekly designation.
            if not str(_r.get("injury_effective","") or "").strip():
                out.at[_idx,"injury_effective"]="ACTIVE"
            if not str(_r.get("injury","") or "").strip():
                out.at[_idx,"injury"]="ACTIVE"
            if not str(_r.get("injury_source","") or "").strip():
                out.at[_idx,"injury_source"]="Sleeper live roster baseline"
            out.at[_idx,"injury_status_verified"]=True
            out.at[_idx,"injury_decision_unresolved"]=False
    return out

def _v789_snapshot_coverage(meta, board_df):
    """Certified coverage survives page navigation; derive only when metadata is absent."""
    meta=meta or {}
    cov=dict(meta.get("coverage",{}) or {})
    b=board_df if isinstance(board_df,pd.DataFrame) else pd.DataFrame()
    def pct_num(col, pred=lambda x:x>0):
        try:
            x=pd.to_numeric(b.get(col,pd.Series(0,index=b.index)),errors="coerce").fillna(0)
            return int(round(100.0*float(pred(x).mean()))) if len(x) else 0
        except Exception:
            return 0
    if "team_coverage" not in cov:
        try:
            _tm=b.get("team",pd.Series("",index=b.index)).fillna("").astype(str).str.upper().str.strip()
            cov["team_coverage"]=int(round(100.0*float((~_tm.isin(["","NFL","FA","NONE","N/A","NAN"])).mean()))) if len(b) else 0
        except Exception:
            cov["team_coverage"]=pct_num("_live_team_verified")
    if "role_conf_coverage" not in cov:
        cov["role_conf_coverage"]=pct_num("_role_confidence",lambda x:x>=60)
    if "role_current_coverage" not in cov:
        try: cov["role_current_coverage"]=int(round(100.0*float(b.get("_usage_recency",pd.Series("",index=b.index)).astype(str).eq("CURRENT").mean()))) if len(b) else 0
        except Exception: cov["role_current_coverage"]=0
    if "role_hist_coverage" not in cov:
        try: cov["role_hist_coverage"]=int(round(100.0*float(b.get("_usage_recency",pd.Series("",index=b.index)).astype(str).eq("PRIOR_SEASON").mean()))) if len(b) else 0
        except Exception: cov["role_hist_coverage"]=0
    if "published_projection_matches" not in cov:
        try:
            avail=b.get("projection_available",pd.Series(False,index=b.index)).fillna(False).astype(bool)
            proj=pd.to_numeric(b.get("projection",pd.Series(index=b.index,dtype=float)),errors="coerce").notna()
            offense=b.get("position",pd.Series("",index=b.index)).astype(str).isin(["QB","RB","WR","TE","K"])
            cov["published_projection_matches"]=int((avail & proj & offense).sum())
        except Exception: cov["published_projection_matches"]=0
    if "weekly_projection_matches" not in cov:
        try: cov["weekly_projection_matches"]=int(pd.to_numeric(b.get("_external_week_projection",pd.Series(index=b.index,dtype=float)),errors="coerce").notna().sum())
        except Exception: cov["weekly_projection_matches"]=0
    return cov

def _v778_fast_context_defaults(df):
    """Offline-safe weekly columns so every page can render immediately."""
    out=df.copy()
    defaults={
        "_opponent":"Schedule cached/unavailable","_matchup_grade":"—",
        "_matchup_adjustment":0.0,"_matchup_source":"Snapshot/local",
        "_role_trend":"NO LIVE ROLE DATA","_role_delta":0.0,"_opps_last":0.0,
        "_touches_last":0.0,"_targets_last":0.0,"_carries_last":0.0,
        "_recent_ppg3":0.0,"_season_ppg_actual":0.0,"_usage_games":0,
        "_usage_source":"Snapshot/local","_usage_recency":"UNAVAILABLE",
        "_snaps_last":0.0,"_snap_pct_last":0.0,"_routes_last":0.0,
        "_route_pct_last":0.0,"_rz_opp_last":0.0,"_role_score_recent":0.0,
        "_role_confidence":55.0,"_role_confidence_source":"snapshot/local",
        "_external_week_projection":np.nan,
    }
    for c,v in defaults.items():
        if c not in out.columns: out[c]=v
    # Canonical injury fields: preserve anything already packaged/saved; otherwise
    # default neutral rather than triggering a network request on navigation.
    inj_defaults={
        "injury_effective":"ACTIVE","injury_source":"Snapshot/local",
        "injury_status_verified":True,"injury_status_quarantined":"",
        "injury_freshness_reason":"snapshot/local","injury_status_conflict":False,
        "injury_status_evidence_expired":False,"injury_decision_unresolved":False,
        "injury_detail":"","practice_status":"","injury_updated":"",
        "practice_source":"","practice_match_status":"snapshot/local",
        "prior_practice_status":"","practice_trend":"","prior_practice_updated":"",
    }
    for c,v in inj_defaults.items():
        if c not in out.columns: out[c]=v
    if "injury" not in out.columns: out["injury"]=out["injury_effective"]
    if "injury_penalty" not in out.columns: out["injury_penalty"]=0.0
    if "injury_severity" not in out.columns: out["injury_severity"]=0

    # V8.08: populate the canonical cross-tab fields vectorially for snapshot/local
    # navigation. Previously the app reached the bottom of app.py and ran several
    # DataFrame.apply() passes over the entire player universe before the page
    # selector could render. On Streamlit Cloud/mobile this could take minutes.
    # An explicit weekly refresh still recomputes the full canonical model below.
    _proj=pd.to_numeric(out.get("projection",pd.Series(0.0,index=out.index)),errors="coerce").fillna(0.0)
    _vorp=pd.to_numeric(out.get("vorp",pd.Series(0.0,index=out.index)),errors="coerce").fillna(0.0)
    _br=pd.to_numeric(out.get("breakout",pd.Series(0.0,index=out.index)),errors="coerce").fillna(0.0).clip(0,1)
    _dc=pd.to_numeric(out.get("decline",pd.Series(0.0,index=out.index)),errors="coerce").fillna(0.0).clip(0,1)
    _conf=pd.to_numeric(out.get("confidence",pd.Series(0.5,index=out.index)),errors="coerce").fillna(0.5).clip(0,1)
    _rc=pd.to_numeric(out.get("_role_confidence",pd.Series(55.0,index=out.index)),errors="coerce").fillna(55.0).clip(0,100)
    _unc=((100.0-_rc)/100.0*2.0).clip(lower=0.6)
    _ros=(_proj + _vorp.clip(-3,5)*0.22 + (_br-_dc)*1.10 + (_conf-0.5)*0.40).clip(lower=0.0)
    _market=pd.to_numeric(out.get("consensus_rank",out.get("market_pick",pd.Series(999.0,index=out.index))),errors="coerce").fillna(999.0)
    _status=out.get("injury_effective",pd.Series("ACTIVE",index=out.index)).fillna("ACTIVE").astype(str).str.upper()
    _role=out.get("_role_trend",pd.Series("STABLE",index=out.index)).fillna("STABLE").astype(str)
    _defaults_fast={
        "fe_team":out.get("team",pd.Series("",index=out.index)).fillna("").astype(str).str.upper(),
        "fe_pos":out.get("position",pd.Series("",index=out.index)).fillna("").astype(str).str.upper(),
        "fe_status":_status,
        "fe_week":_proj.round(3),
        "fe_week_low":(_proj-_unc).clip(lower=0.0).round(3),
        "fe_week_high":(_proj+_unc).round(3),
        "fe_uncertainty":_unc.round(3),
        "fe_ros":_ros.round(3),
        "fe_vorp":_vorp.round(3),
        "fe_market_rank":_market.round(1),
        "fe_role":_role,
        "fe_role_confidence":_rc.round(1),
        "fe_opportunity_score":pd.Series(0.0,index=out.index),
        "fe_opportunity_trend":pd.Series("PREGAME",index=out.index),
        "fe_calibrated_confidence":_rc.round(1),
        "fe_news_impact":pd.Series(0.0,index=out.index),
    }
    for _fc,_fv in _defaults_fast.items():
        if _fc not in out.columns:
            out[_fc]=_fv
    if "fe_key" not in out.columns:
        out["fe_key"]=out.get("player",pd.Series("",index=out.index)).astype(str).map(_owner_key)
    return out

# V8.71: persistent retrieval-timestamp ledger. A failed refresh attempt never
# advances last_successful_fetch_utc, so stale data cannot look fresh.
def _v871_fetch_ledger_get(state_obj):
    raw=(state_obj or {}).get("_source_fetch_ledger",{}) if isinstance(state_obj,dict) else {}
    return dict(raw) if isinstance(raw,dict) else {}

def _v871_fetch_mark_attempt(state_obj, source, when=None):
    if not isinstance(state_obj,dict): return
    when=when or datetime.now(timezone.utc).isoformat()
    led=_v871_fetch_ledger_get(state_obj); row=dict(led.get(str(source),{}) or {})
    row["last_attempt_utc"]=str(when); row["last_attempt_status"]="ATTEMPTED"
    row["last_result"]="ATTEMPTED"; row["attempt_count"]=int(row.get("attempt_count",0) or 0)+1
    led[str(source)]=row; state_obj["_source_fetch_ledger"]=led

def _v871_fetch_mark_success(state_obj, source, when=None, mode="FETCH", provider_timestamp=None, rows=None, detail=None):
    if not isinstance(state_obj,dict): return
    when=when or datetime.now(timezone.utc).isoformat()
    led=_v871_fetch_ledger_get(state_obj); row=dict(led.get(str(source),{}) or {})
    row["last_successful_fetch_utc"]=str(when)
    row["last_attempt_utc"]=str(when)
    row["last_attempt_status"]="SUCCESS"; row["last_result"]="SUCCESS"; row["last_result_utc"]=str(when)
    row["success_mode"]=str(mode or "FETCH").upper(); row["success_count"]=int(row.get("success_count",0) or 0)+1
    if provider_timestamp: row["provider_timestamp_utc"]=str(provider_timestamp)
    if rows is not None:
        try: row["rows_loaded"]=int(rows)
        except Exception: pass
    if detail: row["detail"]=str(detail)[:300]
    row.pop("last_error",None)
    led[str(source)]=row; state_obj["_source_fetch_ledger"]=led

def _v871_fetch_mark_failure(state_obj, source, when=None, error=None):
    if not isinstance(state_obj,dict): return
    when=when or datetime.now(timezone.utc).isoformat()
    led=_v871_fetch_ledger_get(state_obj); row=dict(led.get(str(source),{}) or {})
    row["last_attempt_utc"]=str(when); row["last_attempt_status"]="FAILED"
    row["last_result"]="FAILED"; row["last_result_utc"]=str(when)
    if error: row["last_error"]=str(error)[:300]
    led[str(source)]=row; state_obj["_source_fetch_ledger"]=led

def _v872_fetch_mark_reused(state_obj, source, when=None, detail="last known-good source reused"):
    """Record a refresh decision that reused certified data without faking a new successful-fetch time."""
    if not isinstance(state_obj,dict): return
    when=when or datetime.now(timezone.utc).isoformat()
    led=_v871_fetch_ledger_get(state_obj); row=dict(led.get(str(source),{}) or {})
    row["last_attempt_utc"]=str(when); row["last_attempt_status"]="REUSED"
    row["last_result"]="REUSED"; row["last_result_utc"]=str(when); row["detail"]=str(detail)[:300]
    led[str(source)]=row; state_obj["_source_fetch_ledger"]=led

def _v872_refresh_registry(state_obj, snapshot_meta=None):
    """Persistent per-feed refresh registry, preferring live state and falling back to saved canonical metadata."""
    led=_v871_fetch_ledger_get(state_obj if isinstance(state_obj,dict) else {})
    if not led and isinstance(snapshot_meta,dict):
        led=dict(snapshot_meta.get("source_fetch_ledger",{}) or {})
    return led

# V8.73: transaction-wired refresh registry + conservative bootstrap.
def _v873_iso_utc(value):
    try:
        dt=pd.to_datetime(value,utc=True,errors="coerce")
        if pd.isna(dt): return None
        return dt.to_pydatetime().astimezone(timezone.utc).isoformat()
    except Exception:
        return None

def _v873_bootstrap_refresh_registry(state_obj, snapshot_meta=None, board_df=None):
    """Bootstrap missing successful-fetch timestamps from a certified snapshot.

    This never claims a new network fetch. It only establishes the retrieval age of
    data already certified in the saved weekly snapshot, preserving honest SLA age.
    """
    if not isinstance(state_obj,dict) or not isinstance(snapshot_meta,dict): return False
    changed=False
    ts=_v873_iso_utc(snapshot_meta.get("updated"))
    if not ts: return False
    led=_v871_fetch_ledger_get(state_obj)
    refresh=dict(snapshot_meta.get("refresh_sources",{}) or {})
    has_board=isinstance(board_df,pd.DataFrame) and len(board_df)>0
    evidence={
        "injury": bool(has_board and any(c in board_df.columns for c in ["injury_effective","injury","injury_source"])),
        "usage": bool(has_board and any(c in board_df.columns for c in ["_usage_recency","_role_confidence","_role_trend"])),
        "projection": bool(has_board and any(c in board_df.columns for c in ["_external_week_projection","projection","projection_available"])),
        "board": bool(has_board or snapshot_meta.get("canonical")),
    }
    for src in ["injury","usage","projection","board"]:
        row=dict(led.get(src,{}) or {})
        if row.get("last_successful_fetch_utc") or not evidence.get(src):
            continue
        row.update({
            "last_successful_fetch_utc":ts,
            "last_result":"BOOTSTRAPPED",
            "last_result_utc":ts,
            "success_mode":"CERTIFIED_SNAPSHOT",
            "detail":"bootstrapped from certified weekly snapshot retrieval timestamp; no new fetch claimed",
            "bootstrap_source":"weekly_snapshot_meta.updated",
        })
        if not row.get("last_attempt_utc"): row["last_attempt_utc"]=ts
        led[src]=row; changed=True
    if changed:
        state_obj["_source_fetch_ledger"]=led
    return changed

def _v873_refresh_receipt(state_obj, completed_at=None):
    completed_at=completed_at or datetime.now(timezone.utc).isoformat()
    led=_v871_fetch_ledger_get(state_obj if isinstance(state_obj,dict) else {})
    rows=[]
    for src in ["injury","usage","projection","board"]:
        r=dict(led.get(src,{}) or {})
        rows.append({"source":src,"result":r.get("last_result","UNKNOWN"),
                     "rows":r.get("rows_loaded"),"success":r.get("last_successful_fetch_utc"),
                     "attempt":r.get("last_attempt_utc"),"error":r.get("last_error","")})
    return {"completed_at":completed_at,"version":APP_VERSION,"rows":rows}

def _v873_refresh_receipt_lines(receipt):
    out=[]
    for r in (receipt or {}).get("rows",[]) or []:
        qty=f" • {r.get('rows')} rows" if r.get('rows') is not None else ""
        age=_v867_age_hours_from_ts(r.get("success"))
        out.append(f"{str(r.get('source','')).title()}: {r.get('result','UNKNOWN')}{qty} • successful age {_v868_age_display(age)}")
    return out or ["No completed refresh transaction receipt yet."]

# V8.74: execution receipt + failed-feed recovery UX.
def _v874_local_ct(value):
    try:
        dt=pd.to_datetime(value,utc=True,errors="coerce")
        if pd.isna(dt): return "unknown"
        try:
            from zoneinfo import ZoneInfo
            dt=dt.tz_convert(ZoneInfo("America/Chicago"))
        except Exception:
            dt=dt.tz_convert("US/Central")
        return dt.strftime("%b %-d, %-I:%M:%S %p CT")
    except Exception:
        return str(value or "unknown")

def _v874_refresh_receipt(state_obj, started_at=None, completed_at=None, retry_only=None):
    completed_at=completed_at or datetime.now(timezone.utc).isoformat()
    started_at=started_at or (state_obj or {}).get("_v874_refresh_started_at") or completed_at
    led=_v871_fetch_ledger_get(state_obj if isinstance(state_obj,dict) else {})
    rows=[]
    for src in ["injury","usage","projection","board"]:
        r=dict(led.get(src,{}) or {})
        rows.append({
            "source":src,"result":r.get("last_result","UNKNOWN"),"rows":r.get("rows_loaded"),
            "success":r.get("last_successful_fetch_utc"),"attempt":r.get("last_attempt_utc"),
            "error":r.get("last_error","") or "","detail":r.get("detail","") or "",
        })
    try:
        dur=max(0.0,(pd.to_datetime(completed_at,utc=True)-pd.to_datetime(started_at,utc=True)).total_seconds())
    except Exception:
        dur=None
    _tx=(state_obj or {}).get("_v875_refresh_tx",{}) if isinstance(state_obj,dict) else {}
    return {"started_at":started_at,"completed_at":completed_at,"duration_seconds":dur,"version":APP_VERSION,
            "transaction_id":(_tx or {}).get("transaction_id"),
            "retry_only":list(retry_only or []),"rows":rows}

def _v874_refresh_receipt_lines(receipt):
    if not receipt: return ["No completed refresh transaction receipt yet."]
    out=[]
    if receipt.get("transaction_id"): out.append(f"Transaction: {receipt.get('transaction_id')}")
    _results=[str(r.get("result","UNKNOWN")).upper() for r in (receipt.get("rows",[]) or [])]
    _processed=len(_results)
    _failed=sum(x in {"FAILED","UNKNOWN"} for x in _results)
    _partial=sum(x=="PARTIAL" for x in _results)
    _succ=sum(x=="SUCCESS" for x in _results)
    _reuse=sum(x in {"REUSED","BOOTSTRAPPED"} for x in _results)
    _prefix="PARTIAL FAILURE" if (_failed or _partial) else "COMPLETE"
    out.append(f"{_prefix} • {_processed}/{_processed} sources processed • {_succ} SUCCESS • {_reuse} REUSED • {_partial} PARTIAL • {_failed} FAILED")
    if receipt.get("completed_at"):
        dur=receipt.get("duration_seconds")
        out.append(f"Completed: {_v874_local_ct(receipt.get('completed_at'))}" + (f" • {dur:.1f}s" if isinstance(dur,(int,float)) else ""))
    if receipt.get("retry_only"):
        out.append("Mode: retry failed sources only • "+", ".join(map(str,receipt.get("retry_only") or [])))
    for r in receipt.get("rows",[]) or []:
        qty=f" • {r.get('rows')} rows" if r.get('rows') is not None else ""
        age=_v867_age_hours_from_ts(r.get("success"))
        err=f" • {str(r.get('error'))[:90]}" if r.get("error") else ""
        out.append(f"{str(r.get('source','')).title()}: {r.get('result','UNKNOWN')}{qty} • age {_v868_age_display(age)}{err}")
    return out

def _v876_refresh_compact_lines(receipt):
    if not receipt: return ["No completed refresh transaction receipt yet."]
    rows=list(receipt.get("rows",[]) or [])
    results=[str(r.get("result","UNKNOWN")).upper() for r in rows]
    succ=sum(x=="SUCCESS" for x in results); reuse=sum(x in {"REUSED","BOOTSTRAPPED"} for x in results)
    partial=sum(x=="PARTIAL" for x in results); failed=sum(x in {"FAILED","UNKNOWN"} for x in results)
    state="COMPLETE" if not (partial or failed) else "PARTIAL FAILURE"
    out=[f"{state} • {len(rows)}/{len(rows)} processed • {succ} SUCCESS • {reuse} REUSED • {partial} PARTIAL • {failed} FAILED"]
    if receipt.get("completed_at"):
        dur=receipt.get("duration_seconds")
        out.append(f"{_v874_local_ct(receipt.get('completed_at'))}" + (f" • {dur:.1f}s" if isinstance(dur,(int,float)) else ""))
    if receipt.get("transaction_id"): out.append(f"Transaction {receipt.get('transaction_id')}")
    return out

def _v874_failed_sources_from_receipt(receipt):
    return [str(r.get("source")) for r in (receipt or {}).get("rows",[]) or [] if str(r.get("result","")) in {"FAILED","UNKNOWN"}]

def _v874_freeze_recovery_line(registry_health, call_count=0):
    if registry_health.get("blocking"):
        return "CLEAN FREEZE BLOCKED • stale: "+", ".join(registry_health.get("blocking") or [])
    if registry_health.get("unknown"):
        return "CLEAN FREEZE WAITING • unknown: "+", ".join(registry_health.get("unknown") or [])
    return f"{int(call_count or 0)}/{int(call_count or 0)} calls within source SLAs • CLEAN FREEZE ALLOWED"

def _v875_tx_persist(state_obj):
    try:
        _v809_persist_refresh_state_fast(state_obj)
        return
    except Exception:
        pass
    try:
        save_state(state_obj)
    except Exception:
        pass

def _v875_tx_begin(state_obj, mode="FULL", requested_sources=None, button="Refresh All Sources"):
    import uuid
    now=datetime.now(timezone.utc).isoformat()
    txid=f"RTX-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:6].upper()}"
    tx={
        "transaction_id":txid,"mode":str(mode),"button":str(button),
        "requested_sources":list(requested_sources or ["injury","usage","projection","board"]),
        "button_pressed_at":now,"started_at":None,"updated_at":now,"completed_at":None,
        "stage":"REQUESTED","status":"REQUESTED","message":"Refresh request accepted; waiting for execution.",
        "stage_history":[{"stage":"REQUESTED","at":now}],
    }
    state_obj["_v875_refresh_tx"]=tx
    _v875_tx_persist(state_obj)
    return tx

def _v875_tx_update(state_obj, stage, message=None, status="RUNNING", persist=True):
    if not isinstance(state_obj,dict): return {}
    tx=dict(state_obj.get("_v875_refresh_tx",{}) or {})
    if not tx:
        tx=_v875_tx_begin(state_obj,mode="AUTO",button="Legacy refresh trigger")
    now=datetime.now(timezone.utc).isoformat()
    if not tx.get("started_at") and stage not in {"REQUESTED"}: tx["started_at"]=now
    tx["stage"]=str(stage); tx["status"]=str(status); tx["updated_at"]=now
    if message is not None: tx["message"]=str(message)[:500]
    hist=list(tx.get("stage_history",[]) or [])
    if not hist or hist[-1].get("stage")!=str(stage): hist.append({"stage":str(stage),"at":now})
    tx["stage_history"]=hist[-20:]
    state_obj["_v875_refresh_tx"]=tx
    if persist: _v875_tx_persist(state_obj)
    return tx

def _v875_tx_finish(state_obj, success=True, message=None, receipt=None):
    _rows=(receipt or {}).get("rows",[]) if isinstance(receipt,dict) else []
    _partial=bool(success and any(str(r.get("result","UNKNOWN")) in {"FAILED","UNKNOWN"} for r in _rows if isinstance(r,dict)))
    _status="PARTIAL_FAILURE" if _partial else ("COMPLETE" if success else "FAILED")
    _default=("Refresh committed with one or more failed/unknown feeds; retry failed sources." if _partial else ("Refresh transaction committed." if success else "Refresh transaction failed."))
    tx=_v875_tx_update(state_obj,"COMPLETE" if success else "FAILED",message or _default,_status,persist=False)
    now=datetime.now(timezone.utc).isoformat(); tx["completed_at"]=now
    if isinstance(receipt,dict): tx["receipt_completed_at"]=receipt.get("completed_at")
    state_obj["_v875_refresh_tx"]=tx; _v875_tx_persist(state_obj); return tx

def _v875_tx_lines(tx):
    if not isinstance(tx,dict) or not tx: return ["No refresh request has been recorded yet."]
    lines=[f"Transaction: {tx.get('transaction_id','unknown')} • {tx.get('status','UNKNOWN')}",
           f"Last button press: {_v874_local_ct(tx.get('button_pressed_at'))}",
           f"Current stage: {tx.get('stage','UNKNOWN')}" ]
    if tx.get("message"): lines.append(str(tx.get("message")))
    seq=["STARTING","INJURY","USAGE","PROJECTION","BOARD","COMMITTING","COMPLETE"]
    done={x.get("stage") for x in (tx.get("stage_history",[]) or []) if isinstance(x,dict)}
    stage=tx.get("stage")
    for stg in seq:
        marker="✓" if stg in done and stg!=stage else "→" if stg==stage else "•"
        lines.append(f"{marker} {stg}")
    return lines

def _v875_tx_stale(tx, now=None, minutes=5):
    if not isinstance(tx,dict) or tx.get("status") not in {"REQUESTED","RUNNING"}: return False
    now=now or datetime.now(timezone.utc)
    try:
        dt=pd.to_datetime(tx.get("updated_at"),utc=True,errors="coerce")
        if pd.isna(dt): return False
        return (pd.Timestamp(now)-dt).total_seconds()>float(minutes)*60
    except Exception:
        return False

# V9.18: reconcile stale execution handshakes against the committed refresh receipt.
# A committed receipt is authoritative: REUSED counts as completed work and an older
# RUNNING/USAGE handshake must never survive a successfully committed transaction.
def _v918_reconcile_refresh_handshake(state_obj, receipt=None, persist=True):
    if not isinstance(state_obj,dict): return {}
    tx=dict(state_obj.get("_v875_refresh_tx",{}) or {})
    receipt=receipt or state_obj.get("_v873_last_refresh_receipt") or {}
    if not tx or not isinstance(receipt,dict) or not receipt.get("completed_at"):
        return tx
    tx_status=str(tx.get("status","IDLE")).upper()
    if tx_status not in {"REQUESTED","RUNNING"}:
        return tx
    # Reconcile when this receipt belongs to the same transaction OR is newer than
    # the stale handshake record (covers older builds where transaction_id was not
    # copied consistently into every state object).
    same_id=bool(receipt.get("transaction_id") and receipt.get("transaction_id")==tx.get("transaction_id"))
    try:
        receipt_dt=pd.to_datetime(receipt.get("completed_at"),utc=True,errors="coerce")
        tx_dt=pd.to_datetime(tx.get("updated_at") or tx.get("started_at") or tx.get("button_pressed_at"),utc=True,errors="coerce")
        newer=bool(not pd.isna(receipt_dt) and (pd.isna(tx_dt) or receipt_dt>=tx_dt))
    except Exception:
        newer=False
    if not (same_id or newer):
        return tx
    rows=list(receipt.get("rows",[]) or [])
    results=[str(r.get("result","UNKNOWN")).upper() for r in rows if isinstance(r,dict)]
    failed=any(x in {"FAILED","UNKNOWN"} for x in results)
    partial=any(x=="PARTIAL" for x in results)
    status="PARTIAL_FAILURE" if (failed or partial) else "COMPLETE"
    now=datetime.now(timezone.utc).isoformat()
    hist=list(tx.get("stage_history",[]) or [])
    # Mark every source stage represented by the committed receipt as completed in
    # the audit trail; SUCCESS and REUSED are both terminal source outcomes.
    stage_map={"injury":"INJURY","usage":"USAGE","projection":"PROJECTION","board":"BOARD"}
    seen={str(h.get("stage")) for h in hist if isinstance(h,dict)}
    for r in rows:
        if not isinstance(r,dict): continue
        stg=stage_map.get(str(r.get("source","")).lower())
        if stg and stg not in seen and str(r.get("result","UNKNOWN")).upper() not in {"UNKNOWN"}:
            hist.append({"stage":stg,"at":receipt.get("completed_at") or now}); seen.add(stg)
    for stg in ["COMMITTING","COMPLETE"]:
        if stg not in seen:
            hist.append({"stage":stg,"at":receipt.get("completed_at") or now}); seen.add(stg)
    tx.update({
        "stage":"COMPLETE",
        "status":status,
        "updated_at":now,
        "completed_at":receipt.get("completed_at") or now,
        "receipt_completed_at":receipt.get("completed_at"),
        "message":"Refresh transaction committed; execution handshake reconciled from receipt." if status=="COMPLETE" else "Refresh transaction committed with partial/failed feeds; execution handshake reconciled from receipt.",
        "stage_history":hist[-20:],
        "reconciled_from_receipt":True,
        "reconciled_at":now,
    })
    state_obj["_v875_refresh_tx"]=tx
    if persist:
        _v875_tx_persist(state_obj)
    return tx

# V9.19: the latest completed receipt is the authoritative refresh execution state.
# Session handshake state is only a progress fallback while no completed receipt exists.
def _v919_authoritative_refresh_tx(state_obj, receipt=None, persist=True):
    if not isinstance(state_obj,dict): return {}
    receipt=receipt or state_obj.get("_v873_last_refresh_receipt") or {}
    if not isinstance(receipt,dict) or not receipt.get("completed_at"):
        return dict(state_obj.get("_v875_refresh_tx",{}) or {})
    rows=[r for r in (receipt.get("rows",[]) or []) if isinstance(r,dict)]
    results=[str(r.get("result","UNKNOWN")).upper() for r in rows]
    failed=any(x in {"FAILED","UNKNOWN"} for x in results)
    partial=any(x=="PARTIAL" for x in results)
    status="PARTIAL_FAILURE" if (failed or partial) else "COMPLETE"
    now=datetime.now(timezone.utc).isoformat()
    prior=dict(state_obj.get("_v875_refresh_tx",{}) or {})
    txid=receipt.get("transaction_id") or prior.get("transaction_id")
    hist=[]
    seen=set()
    # Preserve useful history only when it belongs to this transaction; otherwise
    # reconstruct deterministically from the committed receipt.
    if prior and (not txid or prior.get("transaction_id")==txid):
        for h in (prior.get("stage_history",[]) or []):
            if isinstance(h,dict) and h.get("stage"):
                stg=str(h.get("stage"))
                if stg not in seen:
                    hist.append(dict(h)); seen.add(stg)
    stage_map={"injury":"INJURY","usage":"USAGE","projection":"PROJECTION","board":"BOARD"}
    completed_at=receipt.get("completed_at") or now
    for stg in ["STARTING","INJURY","USAGE","PROJECTION","BOARD","COMMITTING","COMPLETE"]:
        if stg=="STARTING":
            should=True
        elif stg in {"COMMITTING","COMPLETE"}:
            should=True
        else:
            should=any(stage_map.get(str(r.get("source","" )).lower())==stg for r in rows)
        if should and stg not in seen:
            hist.append({"stage":stg,"at":completed_at}); seen.add(stg)
    tx={
        "transaction_id":txid,
        "mode":prior.get("mode","FULL"),
        "button":prior.get("button","Refresh All Sources"),
        "requested_sources":prior.get("requested_sources",["injury","usage","projection","board"]),
        "button_pressed_at":prior.get("button_pressed_at") or receipt.get("started_at"),
        "started_at":receipt.get("started_at") or prior.get("started_at"),
        "updated_at":completed_at,
        "completed_at":completed_at,
        "receipt_completed_at":completed_at,
        "stage":"COMPLETE",
        "status":status,
        "message":("Refresh transaction committed; status derived from authoritative receipt." if status=="COMPLETE" else "Refresh transaction committed with partial/failed feeds; status derived from authoritative receipt."),
        "stage_history":hist[-20:],
        "authoritative_from_receipt":True,
        "reconciled_at":now,
    }
    state_obj["_v875_refresh_tx"]=tx
    # Clear any stale per-session stall marker/state by updating the runtime copy too.
    try:
        runtime=dict(st.session_state.get("_v794_runtime_state",{}) or {})
        runtime.update(state_obj)
        runtime["_v875_refresh_tx"]=dict(tx)
        st.session_state["_v794_runtime_state"]=runtime
    except Exception:
        pass
    if persist:
        try: _v809_persist_refresh_state_fast(state_obj)
        except Exception: pass
    return tx

# V9.58.1 hotfix: this helper must be defined before the startup auto-refresh
# planner executes. A later identical definition is intentionally harmless, but
# startup cannot reference a function that Python has not defined yet.
def _v867_age_hours_from_ts(v, now=None):
    now=now or datetime.now(timezone.utc)
    try:
        z=pd.to_datetime(v,errors="coerce",utc=True)
        if pd.isna(z): return None
        return round(max(0.0,(now-z.to_pydatetime().astimezone(timezone.utc)).total_seconds()/3600.0),2)
    except Exception:
        return None

def _v872_registry_health(state_obj, snapshot_meta=None, now=None):
    now=now or datetime.now(timezone.utc)
    led=_v872_refresh_registry(state_obj,snapshot_meta)
    sla={"injury":2.0,"usage":24.0,"projection":6.0,"board":6.0}
    critical={"injury","projection","board"}; rows=[]
    for src,limit in sla.items():
        row=dict(led.get(src,{}) or {}); ts=row.get("last_successful_fetch_utc")
        age=_v867_age_hours_from_ts(ts,now)
        if age is None: status="UNKNOWN"
        elif age<=limit: status="FRESH"
        elif age<=limit*2: status="AGING"
        else: status="STALE"
        rows.append({"source":src,"age_hours":age,"sla_hours":limit,"status":status,
                     "last_result":row.get("last_result",row.get("last_attempt_status","UNKNOWN")),
                     "last_successful_fetch_utc":ts,"last_attempt_utc":row.get("last_attempt_utc"),
                     "last_error":row.get("last_error","")})
    blocking=[r["source"] for r in rows if r["source"] in critical and r["status"]=="STALE"]
    unknown=[r["source"] for r in rows if r["source"] in critical and r["status"]=="UNKNOWN"]
    overall="BLOCKING WARNING" if blocking else "CAUTION" if unknown or any(r["status"] in {"AGING","STALE"} for r in rows) else "FRESH"
    return {"status":overall,"rows":rows,"blocking":blocking,"unknown":unknown}

def _v872_registry_health_lines(state_obj, snapshot_meta=None, now=None):
    h=_v872_registry_health(state_obj,snapshot_meta,now)
    lines=[]
    for r in h["rows"]:
        lines.append(f"{r['source'].title()}: {_v868_age_display(r['age_hours'])} • {r['status']} • last refresh {r['last_result']}")
    if h["blocking"]: lines.append("Blocking source(s): "+", ".join(h["blocking"]))
    elif h["unknown"]: lines.append("Missing successful-fetch timestamp: "+", ".join(h["unknown"]))
    else: lines.append("All critical source registries have a successful retrieval timestamp within policy.")
    return lines

# V9.58: automatic refresh-ledger planner. This is intentionally a planner only:
# it never mutates frozen prediction/bias ledgers and never advances a successful
# fetch timestamp by itself. The normal provider transaction remains authoritative.
_V958_AUTO_REFRESH_COOLDOWN_MINUTES=15
# V9.59: never let stale-source maintenance monopolize cold startup. The app renders
# the certified snapshot first, then the heartbeat may request ONE bounded source at
# a time. This keeps mobile/Cloud navigation responsive even when a provider is slow.
_V959_AUTO_STARTUP_GRACE_SECONDS=45
_V959_AUTO_MAX_SOURCES_PER_PASS=1
_V959_AUTO_LIVE_SOURCE_BUDGET_SECONDS=2.5

def _v958_auto_refresh_plan(state_obj, snapshot_meta=None, now=None, cooldown_minutes=_V958_AUTO_REFRESH_COOLDOWN_MINUTES):
    now=now or datetime.now(timezone.utc)
    health=_v872_registry_health(state_obj,snapshot_meta,now)
    # Refresh genuinely stale/unknown feeds only. AGING remains visible but does not
    # cause background provider traffic before its SLA is actually exceeded.
    sources=[str(r.get("source")) for r in (health.get("rows",[]) or [])
             if str(r.get("status","")).upper() in {"STALE","UNKNOWN"}]
    sources=[x for x in ["injury","usage","projection","board"] if x in set(sources)]
    tx=dict((state_obj or {}).get("_v875_refresh_tx",{}) or {}) if isinstance(state_obj,dict) else {}
    running=str(tx.get("status","IDLE")).upper() in {"REQUESTED","RUNNING"}
    meta=dict((state_obj or {}).get("_v958_auto_refresh",{}) or {}) if isinstance(state_obj,dict) else {}
    last=meta.get("last_attempt_utc")
    age_min=None
    try:
        dt=pd.to_datetime(last,utc=True,errors="coerce")
        if not pd.isna(dt): age_min=max(0.0,(pd.Timestamp(now)-dt).total_seconds()/60.0)
    except Exception:
        age_min=None
    cooling=bool(age_min is not None and age_min<float(cooldown_minutes))
    due=bool(sources and not running and not cooling)
    return {
        "due":due,"sources":sources,"health":health,"running":running,"cooling_down":cooling,
        "cooldown_minutes":float(cooldown_minutes),"minutes_since_attempt":age_min,
        "last_attempt_utc":last,"last_completed_utc":meta.get("last_completed_utc"),
    }

def _v958_mark_auto_refresh_attempt(state_obj, sources, now=None):
    if not isinstance(state_obj,dict): return
    now=now or datetime.now(timezone.utc).isoformat()
    meta=dict(state_obj.get("_v958_auto_refresh",{}) or {})
    meta.update({"enabled":True,"last_attempt_utc":str(now),"last_sources":list(sources or []),"last_version":APP_VERSION})
    state_obj["_v958_auto_refresh"]=meta

def _v958_mark_auto_refresh_complete(state_obj, receipt=None, now=None):
    if not isinstance(state_obj,dict): return
    now=now or datetime.now(timezone.utc).isoformat()
    meta=dict(state_obj.get("_v958_auto_refresh",{}) or {})
    meta.update({"enabled":True,"last_completed_utc":str(now)})
    if isinstance(receipt,dict):
        meta["last_transaction_id"]=receipt.get("transaction_id")
        meta["last_receipt_completed_at"]=receipt.get("completed_at")
    state_obj["_v958_auto_refresh"]=meta

def _v958_auto_refresh_status_line(state_obj, snapshot_meta=None):
    plan=_v958_auto_refresh_plan(state_obj,snapshot_meta)
    base=f"Automatic refresh: ON • one stale/unknown feed per pass • {int(plan['cooldown_minutes'])}m retry cooldown"
    if plan.get("running"): return base+" • refresh currently running"
    if plan.get("cooling_down") and plan.get("sources"):
        remain=max(0,int(round(plan['cooldown_minutes']-float(plan.get('minutes_since_attempt') or 0))))
        return base+f" • retry cooldown {remain}m • pending: "+", ".join(plan.get("sources") or [])
    if plan.get("sources"): return base+" • next app check will refresh: "+", ".join(plan.get("sources") or [])
    return base+" • ledger within policy"

@st.cache_data(ttl=1800, show_spinner=False)
def _v815_nfl_state_preflight():
    """Early refresh-safe NFL season/week lookup.

    Defined before the startup refresh block so Streamlit cannot hit a runtime
    NameError while the later legacy _v677_nfl_state helper is still being
    defined farther down the script.
    """
    try:
        r=requests.get("https://api.sleeper.app/v1/state/nfl",timeout=6)
        r.raise_for_status()
        d=r.json() if isinstance(r.json(),dict) else {}
        return {
            "season":int(d.get("season") or datetime.now().year),
            "week":max(1,int(d.get("week") or d.get("leg") or 1)),
        }
    except Exception:
        return {"season":datetime.now().year,"week":1}

