# V9.16 REFRESH PROFILER -----------------------------------------------------
# Lightweight wall-clock tracing stored in session/state. This deliberately does
# not make any network calls and adds only perf_counter bookkeeping.
def _v916_profiler_begin():
    return {"started_perf":time.perf_counter(),"started_at":datetime.now(timezone.utc).isoformat(),"stages":{},"sources":{},"version":APP_VERSION}

def _v916_profiler_mark(profile,label,started,status="OK",detail=""):
    if not isinstance(profile,dict): return
    profile.setdefault("stages",{})[str(label)]={
        "seconds":round(max(0.0,time.perf_counter()-float(started)),3),
        "status":str(status),"detail":str(detail or "")
    }

def _v916_profiler_source(profile,label,seconds,status,detail=""):
    if not isinstance(profile,dict): return
    profile.setdefault("sources",{})[str(label)]={"seconds":round(float(seconds),3),"status":str(status),"detail":str(detail or "")}

def _v916_profiler_finish(profile):
    if not isinstance(profile,dict): return profile
    try: profile["total_seconds"]=round(time.perf_counter()-float(profile.get("started_perf",time.perf_counter())),3)
    except Exception: profile["total_seconds"]=None
    profile["completed_at"]=datetime.now(timezone.utc).isoformat()
    profile.pop("started_perf",None)
    # identify the dominant measured stage/source for field diagnosis
    candidates=[]
    for grp in ("stages","sources"):
        for k,v in (profile.get(grp,{}) or {}).items():
            try: candidates.append((float(v.get("seconds",0) or 0),k,str(v.get("status",""))))
            except Exception: pass
    if candidates:
        sec,name,status=max(candidates)
        profile["bottleneck"]={"name":name,"seconds":round(sec,3),"status":status}
    return profile

def _v962_certify_waiver_handoff(state_obj, snapshot_meta, board_rows=0, receipt=None):
    """Commit an explicit current-version Waiver certification after board persistence.

    This is intentionally called only after the canonical weekly board has been saved.
    It does not fetch providers or change projections; it synchronizes the build receipt
    that Waivers uses to decide whether live recommendations are safe to render.
    """
    if not isinstance(state_obj,dict):
        return snapshot_meta if isinstance(snapshot_meta,dict) else {}
    now=datetime.now(timezone.utc).isoformat(timespec="seconds")
    meta=dict(snapshot_meta or state_obj.get("_weekly_board_snapshot_meta",{}) or {})
    src=dict(state_obj.get("_weekly_refresh_sources",{}) or meta.get("refresh_sources",{}) or {})
    src["_build"]={"ok":True,"version":APP_VERSION,"updated":now,"mode":"post-commit-certified"}
    # These three are the invariant inputs required by the Waiver engine. During the
    # incremental weekly refresh they are deliberately reused from the certified base.
    # A successful canonical board commit certifies that reuse for this app version.
    for k,mode in (("base_model","canonical-board-certified"),("history","certified-base-reused"),("market","certified-base-reused")):
        prev=dict(src.get(k,{}) or {})
        prev.update({"ok":True,"mode":prev.get("mode") or mode})
        src[k]=prev
    txid=(receipt or {}).get("transaction_id") if isinstance(receipt,dict) else None
    cert={
        "ok":True,"version":APP_VERSION,"certified_at":now,"rows":int(board_rows or meta.get("rows",0) or 0),
        "transaction_id":txid,"reason":"canonical weekly board committed successfully",
    }
    meta["refresh_sources"]=src
    meta["waiver_certification"]=cert
    state_obj["_weekly_refresh_sources"]=src
    state_obj["_weekly_board_snapshot_meta"]=meta
    try:
        runtime=dict(st.session_state.get("_v794_runtime_state",{}) or {})
        runtime.update(state_obj)
        runtime["_weekly_refresh_sources"]=dict(src)
        runtime["_weekly_board_snapshot_meta"]=dict(meta)
        st.session_state["_v794_runtime_state"]=runtime
    except Exception:
        pass
    return meta

def _v916_show_refresh_profile(profile):
    if not isinstance(profile,dict) or not profile: return
    total=profile.get("total_seconds")
    bott=profile.get("bottleneck",{}) or {}
    if total is not None:
        icon="⚡" if float(total)<=8 else ("🟡" if float(total)<=12 else "🔴")
        st.sidebar.caption(f"{icon} Last refresh: {float(total):.2f}s")
    with st.sidebar.expander("⏱ Refresh diagnostics",expanded=False):
        if total is not None: st.write(f"**Total backend refresh:** {float(total):.2f}s")
        if bott: st.write(f"**Longest measured step:** {bott.get('name')} • {float(bott.get('seconds',0)):.2f}s • {bott.get('status','')}")
        src=profile.get("sources",{}) or {}
        if src:
            rows=[]
            for name,v in src.items(): rows.append({"Source":name,"Seconds":v.get("seconds"),"Status":v.get("status"),"Detail":v.get("detail","")})
            st.dataframe(pd.DataFrame(rows),use_container_width=True,hide_index=True)
        stages=profile.get("stages",{}) or {}
        if stages:
            rows=[]
            for name,v in stages.items(): rows.append({"Stage":name,"Seconds":v.get("seconds"),"Status":v.get("status"),"Detail":v.get("detail","")})
            st.dataframe(pd.DataFrame(rows),use_container_width=True,hide_index=True)
        st.caption("Target: 8–12s repeat refresh • LIVE = fetched now • CACHE/REUSED/DEFERRED = no live wait • TIMEOUT/FALLBACK = provider did not block beyond its budget.")

# Fast startup: render from the certified local board immediately.
# V9.58: every normal Streamlit rerun also checks the persistent source ledger.
# If a feed is truly STALE/UNKNOWN, the existing transaction engine refreshes only
# those feeds automatically. Manual controls remain available as an override.
_v794_manual_forced_refresh=bool(st.session_state.pop("_v794_force_weekly_refresh",False))
_v874_manual_retry_only=set(st.session_state.pop("_v874_retry_sources",[]) or []) if _v794_manual_forced_refresh else set()
_v958_sidebar_refresh=st.sidebar.button(
    "↻ Refresh weekly data now",
    help="Runs one full live rebuild, saves the certified snapshot, then returns to instant page navigation.",
    use_container_width=True,
)
_v958_auto_plan=_v958_auto_refresh_plan(state,_v778_snapshot_meta)
# V9.59 cold-start guard. A stale ledger must not turn opening the app into a blocking
# provider transaction. Render the saved board first; automatic maintenance becomes
# eligible after a short session grace period or when the heartbeat explicitly queues it.
if "_v959_session_started_perf" not in st.session_state:
    st.session_state["_v959_session_started_perf"]=time.perf_counter()
_v959_session_age_s=max(0.0,time.perf_counter()-float(st.session_state.get("_v959_session_started_perf",time.perf_counter())))
_v959_heartbeat_requested=bool(st.session_state.pop("_v959_auto_refresh_requested",False))
_v959_auto_eligible=bool(_v959_heartbeat_requested or _v959_session_age_s>=_V959_AUTO_STARTUP_GRACE_SECONDS)
# The sidebar button starts a fresh audited transaction too; it must not reuse the
# transaction id/status from an older completed receipt.
if _v958_sidebar_refresh and not _v794_manual_forced_refresh:
    _v875_tx_begin(state,mode="FULL",requested_sources=["injury","usage","projection","board"],button="Refresh weekly data now")
_v958_auto_trigger=bool((not _v794_manual_forced_refresh) and (not _v958_sidebar_refresh) and _v959_auto_eligible and _v958_auto_plan.get("due"))
if _v958_auto_trigger:
    # One source per automatic pass. A slow injury feed cannot also drag usage,
    # projection, and board work through the same mobile rerun.
    _v958_auto_sources=list(_v958_auto_plan.get("sources",[]) or [])[:_V959_AUTO_MAX_SOURCES_PER_PASS]
    _v958_mark_auto_refresh_attempt(state,_v958_auto_sources)
    _v875_tx_begin(state,mode="AUTO_STALE_BOUNDED",requested_sources=_v958_auto_sources,button="Automatic bounded stale-source refresh")
    try: _v809_persist_refresh_state_fast(state)
    except Exception: pass
else:
    _v958_auto_sources=[]
_v794_forced_refresh=bool(_v794_manual_forced_refresh or _v958_sidebar_refresh or _v958_auto_trigger)
_v874_retry_only=(set(_v874_manual_retry_only) if _v794_manual_forced_refresh else (set(_v958_auto_sources) if _v958_auto_trigger else set()))
_refresh_live=_v794_forced_refresh
if _v958_auto_trigger:
    st.sidebar.caption("↻ Automatic ledger refresh • "+", ".join(_v958_auto_sources))
if not _refresh_live:
    if _v778_snapshot_loaded:
        _v778_when=str(_v778_snapshot_meta.get("updated","Saved snapshot"))
        st.sidebar.caption(f"⚡ Instant snapshot active • {_v778_when}")
    else:
        st.sidebar.caption("⚡ Instant local mode • run weekly refresh once to save live weekly context")
_v778_network_allowed=bool(_refresh_live)
if _refresh_live:
    st.session_state["v921_load_deep_calibration"]=False
    _v916_profile=_v916_profiler_begin()
    st.session_state["_v916_active_refresh_profile"]=_v916_profile
    _v875_tx_update(state,"STARTING","Refresh engine started and source attempts are being registered.",persist=True)
    # V8.74: one transaction start time powers duration receipts. A failed-only
    # retry targets only the requested volatile feeds; board is always persisted
    # because it is the canonical output transaction.
    _v871_attempt_ts=datetime.now(timezone.utc).isoformat()
    state["_v874_refresh_started_at"]=_v871_attempt_ts
    _v874_attempt_sources=set(_v874_retry_only or ["injury","usage","projection","board"]) | {"board"}
    for _v871_src in ["injury","usage","projection","board"]:
        if _v871_src in _v874_attempt_sources:
            _v871_fetch_mark_attempt(state,_v871_src,_v871_attempt_ts)
    # V8.13 FAST WEEKLY REFRESH: never clear the entire Streamlit cache.
    # Only live/current-week providers are invalidated. Slow historical/model
    # sources remain cached and are not redownloaded just to update Waivers.
    # V9.15 FAST REFRESH: invalidate only the truly volatile lightweight feeds.
    # Expensive injury/practice corroboration already has a short 15-minute TTL and
    # is layered on top of the freshly downloaded Sleeper directory. Clearing those
    # caches on every click forced ESPN/nflverse round-trips and made repeat refreshes
    # take 10-20+ seconds. They now refresh automatically when their TTL expires.
    for _v813_fn in [
        sleeper_players,
        _v815_nfl_state_preflight,
        globals().get("_v692_sleeper_weekly_projections"),
    ]:
        try:
            if _v813_fn is not None and hasattr(_v813_fn,"clear"):
                _v813_fn.clear()
        except Exception:
            pass
    state.pop("_weekly_board_snapshot_gz",None)

if _refresh_live:
    # V7.93 MODULAR REFRESH: one failed provider can no longer throw away good data
    # from every other provider. Start from the last known-good snapshot/local board,
    # then improve it source-by-source. This fixes the old all-or-nothing refresh path
    # where an nflverse/history failure silently discarded a successful Sleeper team
    # directory and left Waivers with team="NFL" and 0% coverage.
    _v803_startup.info("Updating live data; the current saved board remains available after refresh.")
    with st.spinner("Refreshing weekly data once…"):
        _v802_progress=st.empty()
        _v802_progress.info("Refresh step 1/6: player directory")
        board=_v778_snapshot_board.copy() if _v778_snapshot_loaded else _fast_local_draft_board()
        board=_v778_fast_context_defaults(board)
        players={}
        hist=pd.DataFrame()
        market=pd.DataFrame()
        _v793_sources={"_build":{"ok":True,"version":APP_VERSION,"updated":datetime.now(timezone.utc).isoformat(timespec="seconds")}}

        # V8.13: routine weekly refresh is incremental. The saved/bundled
        # certified model remains the base; only volatile weekly sources refresh.
        _v802_progress.info("Refresh step 1/4: current player + injury truth")
        try:
            # V9.16: one OUTER wall-clock budget for all startup live futures.
            # V9.15 bounded the inner injury providers, but awaiting these futures
            # one-by-one could still stack waits. No startup provider may extend this
            # stage beyond 6 seconds total.
            _v916_stage_t=time.perf_counter()
            _v813_pool=concurrent.futures.ThreadPoolExecutor(max_workers=4)
            try:
                _v916_submitted={}
                # V9.59 selective prerequisites. Retry/auto passes fetch only what the
                # requested source needs instead of always firing four providers.
                _v959_requested=set(_v874_retry_only or ["injury","usage","projection","board"])
                _v959_jobs=[]
                if (not _v874_retry_only) or bool(_v959_requested & {"injury","board"}):
                    _v959_jobs.append(("Sleeper directory",sleeper_players))
                if (not _v874_retry_only) or "injury" in _v959_requested:
                    _v959_jobs.extend([("Injury corroboration",_v680_injury_watch_feed),("ESPN roster status",_v679_espn_roster_status)])
                if (not _v874_retry_only) or bool(_v959_requested & {"injury","projection","board"}):
                    _v959_jobs.append(("NFL state",_v815_nfl_state_preflight))
                for _name,_fn in _v959_jobs:
                    _t=time.perf_counter(); _f=_v813_pool.submit(_fn); _v916_submitted[_f]=(_name,_t)
                _v959_live_budget=_V959_AUTO_LIVE_SOURCE_BUDGET_SECONDS if _v958_auto_trigger else 4.0
                if _v916_submitted:
                    _done,_pending=concurrent.futures.wait(set(_v916_submitted),timeout=_v959_live_budget)
                else:
                    _done,_pending=set(),set()
                players={}; _v813_injury_prefetch={}; _v813_roster_prefetch={}; _v813_live_state={
                    "season":int((_v778_snapshot_meta or {}).get("season",datetime.now().year) or datetime.now().year),
                    "week":int((_v778_snapshot_meta or {}).get("week",1) or 1),
                }
                for _f in _done:
                    _name,_t=_v916_submitted[_f]
                    try:
                        _val=_f.result()
                        _v916_profiler_source(_v916_profile,_name,time.perf_counter()-_t,"LIVE","completed inside shared 4s budget")
                        if _name=="Sleeper directory": players=_val if isinstance(_val,dict) else {}
                        elif _name=="Injury corroboration": _v813_injury_prefetch=_val or {}
                        elif _name=="ESPN roster status": _v813_roster_prefetch=_val or {}
                        else: _v813_live_state=_val if isinstance(_val,dict) else _v813_live_state
                    except Exception as _e:
                        _v916_profiler_source(_v916_profile,_name,time.perf_counter()-_t,"FALLBACK",f"{type(_e).__name__}: {_e}")
                for _f in _pending:
                    _name,_t=_v916_submitted[_f]
                    _f.cancel()
                    _v916_profiler_source(_v916_profile,_name,min(_v959_live_budget,time.perf_counter()-_t),"TIMEOUT",f"shared {_v959_live_budget:.1f}s startup budget exhausted; fallback retained")
                if not players:
                    _v793_sources["sleeper"]={"ok":False,"error":"timeout/unavailable within shared 4s budget"}
                if _v813_injury_prefetch:
                    _v793_sources["injury_prefetch"]={"ok":True,"rows":len(_v813_injury_prefetch) if hasattr(_v813_injury_prefetch,"__len__") else 0}
                else:
                    _v793_sources["injury_prefetch"]={"ok":False,"mode":"timeout-or-fallback"}
            finally:
                _v813_pool.shutdown(wait=False,cancel_futures=True)
            _v916_profiler_mark(_v916_profile,"startup live sources",_v916_stage_t)
            if not isinstance(players,dict) or not players:
                raise RuntimeError("Sleeper player directory returned no records")
            _v793_sources["sleeper"]={"ok":True,"rows":len(players)}
            board=_v792_apply_raw_sleeper_truth(board,players)
        except Exception as _e:
            players=players if isinstance(players,dict) else {}
            _v793_sources.setdefault("sleeper",{"ok":False,"error":f"{type(_e).__name__}: {_e}"})

        # The local/saved board is already the certified base model. Historical
        # archives and market ECR are slow-changing inputs and are not part of a
        # routine weekly injury/projection refresh.
        hist=pd.DataFrame(); market=pd.DataFrame()
        _v793_sources["history"]={"ok":True,"mode":"certified-base-reused"}
        _v793_sources["market"]={"ok":True,"mode":"certified-base-reused"}
        _v793_sources["base_model"]={"ok":True,"mode":"incremental-weekly-refresh","rows":int(len(board))}

        # Injury overlay can fetch team reports; show this separately from model work.
        _v875_tx_update(state,"INJURY","Reconciling injury/status sources.",persist=True)
        _v802_progress.info("Refresh step 2/4: reconciling injury reports")
        # Injury overlay must never be coupled to whether history/market rebuild succeeded.
        if _v874_retry_only and "injury" not in _v874_retry_only:
            _v793_sources["injury_overlay"]={"ok":True,"mode":"retry-not-requested-reused"}
            _v872_fetch_mark_reused(state,"injury",detail="retry-failed-only: prior injury source retained")
        else:
            try:
                _v916_stage_t=time.perf_counter()
                board=apply_v92_injury_overlay(board,state, injury_watch_prefetch=locals().get("_v813_injury_prefetch",{}), roster_status_prefetch=locals().get("_v813_roster_prefetch",{}))
                _v916_profiler_mark(_v916_profile,"injury overlay",_v916_stage_t,"OK","cached/certified corroboration preferred")
                _v793_sources["injury_overlay"]={"ok":True}
                _v871_fetch_mark_success(state,"injury",mode="FETCH",rows=len(board),detail="injury overlay reconciled")
            except Exception as _e:
                _v916_profiler_mark(_v916_profile,"injury overlay",locals().get("_v916_stage_t",time.perf_counter()),"FALLBACK",f"{type(_e).__name__}: {_e}")
                _v793_sources["injury_overlay"]={"ok":False,"error":f"{type(_e).__name__}: {_e}"}
                _v871_fetch_mark_failure(state,"injury",error=_e)

        # Re-apply Sleeper truth after injury/model overlays so current team identity
        # survives every legacy merge path.
        if isinstance(players,dict) and players:
            try:
                board=_v792_apply_raw_sleeper_truth(board,players)
            except Exception:
                pass

        _v802_progress.info("Refresh step 3/4: projections, matchup, and usage")
        state["_weekly_refresh_sources"]=_v793_sources
        st.session_state["_v794_runtime_state"]=dict(state)
        _ok_sources=[k for k,v in _v793_sources.items() if isinstance(v,dict) and v.get("ok")]
        if _ok_sources:
            st.sidebar.success("Weekly sources refreshed: "+", ".join(_ok_sources))
        _failed_sources=[k for k,v in _v793_sources.items() if isinstance(v,dict) and not v.get("ok")]
        if _failed_sources:
            st.sidebar.warning("Some sources unavailable; last known-good data retained for: "+", ".join(_failed_sources))
else:
    # Critical V7.78 behavior: page clicks NEVER call Sleeper/ESPN/nflverse.
    players={}
    hist=pd.DataFrame(); market=pd.DataFrame()
    board=_v778_snapshot_board.copy() if _v778_snapshot_loaded else _fast_local_draft_board()
    board=_v778_fast_context_defaults(board)

# V7.89: page navigation restores verified team identity from the saved weekly truth.
