# ---------------- V7.55 unified intelligence layer ----------------
# One canonical player-state record now feeds every downstream surface.  The layer
# deliberately uses fields already present on the production board; it does not invent
# snaps, injuries, or market information when a source is unavailable.
def _v755_num(row, key, default=0.0):
    try:
        v=row.get(key, default)
        if v is None or pd.isna(v): return float(default)
        return float(v)
    except Exception:
        return float(default)

def _v755_player_state_row(row):
    """Canonical cross-tab player state: identity, value, health, role and confidence."""
    proj=_v755_num(row,"projection",0)
    ext=row.get("_external_week_projection",np.nan)
    try: ext=float(ext) if ext is not None and not pd.isna(ext) else np.nan
    except Exception: ext=np.nan
    recent=_v755_num(row,"_recent_ppg3",0)
    actual=_v755_num(row,"_season_ppg_actual",0)
    rc=max(0.0,min(100.0,_v755_num(row,"_role_confidence",0)))
    # Ensemble: model is the anchor; external projection and actual production only
    # contribute when they really exist.  Early-season observed production is capped.
    vals=[(proj,.58)]
    if not pd.isna(ext): vals.append((ext,.27))
    if recent>0: vals.append((recent,.10))
    elif actual>0: vals.append((actual,.07))
    wsum=sum(w for _,w in vals) or 1.0
    ensemble=sum(v*w for v,w in vals)/wsum
    dispersion=[]
    for v,_ in vals: dispersion.append(abs(v-ensemble))
    disagreement=(sum(dispersion)/len(dispersion)) if dispersion else 0.0
    uncertainty=max(0.6, disagreement + (100.0-rc)/100.0*2.0)
    lo=max(0.0,ensemble-uncertainty); hi=ensemble+uncertainty
    ros=_v682_ros_value(row)
    vorp=_v755_num(row,"vorp",_v755_num(row,"VORP",0))
    market=_v755_num(row,"consensus_rank",_v755_num(row,"market_pick",999))
    status=_v677_normalize_injury_status(row.get("injury_effective",row.get("injury","")))
    role=str(row.get("_role_trend","") or "STABLE")
    team=str(row.get("team","") or "").upper()
    pos=str(row.get("position","") or "").upper()
    return pd.Series({
        "fe_key":_owner_key(row.get("player","")),"fe_team":team,"fe_pos":pos,
        "fe_status":status,"fe_week":round(ensemble,3),"fe_week_low":round(lo,3),
        "fe_week_high":round(hi,3),"fe_uncertainty":round(uncertainty,3),
        "fe_ros":round(float(ros),3),"fe_vorp":round(vorp,3),"fe_market_rank":round(market,1),
        "fe_role":role,"fe_role_confidence":round(rc,1),
    })

def _v755_usage_signal(row):
    """Role/opportunity signal from real observed usage fields only."""
    games=_v755_num(row,"_usage_games",0)
    if games<=0 or str(row.get("_usage_recency","")).upper()!="CURRENT":
        return 0.0,"PREGAME"
    snap=_v755_num(row,"_snap_pct_last",0); route=_v755_num(row,"_route_pct_last",0)
    rz=_v755_num(row,"_rz_opp_last",0); recent=_v755_num(row,"_recent_ppg3",0); season=_v755_num(row,"_season_ppg_actual",0)
    score=(snap-.55)*42.0 + (route-.55)*26.0 + min(12.0,rz*2.0)
    if season>0 and recent>0: score += max(-12,min(12,(recent-season)*1.4))
    label="RISING" if score>=8 else ("FALLING" if score<=-8 else "STABLE")
    return round(score,2),label

def _v755_quality_flags(board_df):
    """V7.60 data-quality classifier.

    Separate truly unsafe records from explainable model disagreement.  Only BLOCK
    records are allowed to stop/certification-warn live roster decisions.  REVIEW
    records remain visible in diagnostics but do not make the whole app look unsafe.
    """
    if board_df is None or board_df.empty: return pd.DataFrame()
    rows=[]
    keys=board_df.get("fe_key",board_df["player"].map(_owner_key))
    key_counts=keys.value_counts()
    valid_pos={"QB","RB","WR","TE","K","DL","DB"}
    for _,r in board_df.iterrows():
        flags=[]; severity="REVIEW"; resolution=[]
        key=str(r.get("fe_key",_owner_key(r.get("player",""))))
        market=_v755_num(r,"fe_market_rank",999); ros=_v755_num(r,"fe_ros",0); wk=_v755_num(r,"fe_week",0)
        vorp=_v755_num(r,"fe_vorp",0)
        pos=str(r.get("position",r.get("fe_pos","")) or "").upper()
        team=str(r.get("fe_team",r.get("team","")) or "").upper()
        reconciled=str(r.get("fe_status",r.get("injury_effective","ACTIVE")) or "ACTIVE").upper()
        verified=bool(r.get("injury_status_verified",True))
        quarantined=str(r.get("injury_status_quarantined","") or "").upper()
        conflict=bool(r.get("injury_status_conflict",False))
        decision_unresolved=bool(r.get("injury_decision_unresolved", (not verified) or conflict or bool(quarantined)))
        if key_counts.get(key,0)>1:
            flags.append("duplicate identity"); severity="BLOCK"; resolution.append("deduplicate canonical identity")
        # Missing team is unsafe for a current NFL player because schedule/role joins can cross-wire.
        if pos in valid_pos and not team:
            flags.append("missing live team"); severity="BLOCK"; resolution.append("resolve current NFL team")
        # Reconciled status is authoritative.  Never flag a legacy raw injury string when a
        # verified reconciliation has already cleared it; this was a major false-positive source.
        if decision_unresolved:
            flags.append("unresolved status evidence")
            # Only a current severe unresolved label is blocking; otherwise keep as review.
            if quarantined in ("OUT","IR","PUP","NFI","SUSPENDED") or conflict:
                severity="BLOCK"
            resolution.append("use reconciled/fresh status only")
        # Market disagreements are model diagnostics, not automatically corrupt data.
        # Escalate only when BOTH the weekly/ROS value and VORP are implausibly low for a
        # highly ranked offensive asset.  K/IDP values live on different scales.
        if pos in ("QB","RB","WR","TE") and market<=75 and ros<2.0 and wk<3.0:
            flags.append("market/value disagreement")
            resolution.append("blend market anchor with projection ensemble")
            if market<=35 and vorp < -4:
                severity="BLOCK"
        elif pos in ("QB","RB","WR","TE") and market<=40 and vorp < -4:
            flags.append("market/VORP disagreement")
            resolution.append("soft market anchor applied")
        if flags:
            rows.append({"Player":r.get("player",""),"Severity":severity,"Flags":" • ".join(flags),"Resolution":" • ".join(dict.fromkeys(resolution))})
    return pd.DataFrame(rows)

def _v755_transaction_sim(my_df, add_row=None, drop_row=None):
    """Whole-roster transaction simulation: weekly lineup, ROS and resilience deltas."""
    if my_df is None or my_df.empty: return {"week":0.0,"ros":0.0,"resilience":0.0,"total":0.0}
    before_week=float(_v676_roster_score(my_df))
    before_ros=float(pd.to_numeric(my_df.get("fe_ros",pd.Series(0,index=my_df.index)),errors="coerce").fillna(0).nlargest(min(10,len(my_df))).sum())
    def resil(df):
        # surplus playable depth above required positional starters
        slots=(state or {}).get("roster_slots",{})
        total=0.0
        for pos in ("QB","RB","WR","TE","K","DL","DB"):
            need=max(1,int(slots.get(pos,0) or 0))
            playable=df[(df["position"].astype(str)==pos) & ~df.get("fe_status",df.get("injury",pd.Series(index=df.index,dtype=str))).astype(str).isin(["OUT","IR","PUP","NFI","SUSPENDED"])]
            total += max(0,len(playable)-need)*.35
        return total
    before_res=resil(my_df)
    after=my_df.copy()
    if drop_row is not None: after=after[~after["player"].eq(str(drop_row.get("player","")))].copy()
    if add_row is not None: after=pd.concat([after,pd.DataFrame([add_row])],ignore_index=True)
    after_week=float(_v676_roster_score(after))
    after_ros=float(pd.to_numeric(after.get("fe_ros",pd.Series(0,index=after.index)),errors="coerce").fillna(0).nlargest(min(10,len(after))).sum())
    dr=round(resil(after)-before_res,2); dw=round(after_week-before_week,2); dros=round((after_ros-before_ros)/10.0,2)
    return {"week":dw,"ros":dros,"resilience":dr,"total":round(dw*.55+dros*.30+dr*.15,2)}

def _v755_league_context(board_df,state_snapshot):
    rows=[]
    for pos in ("QB","RB","WR","TE","K","DL","DB"):
        b=board_df[board_df["position"].astype(str).eq(pos)]
        rostered=int(b["player"].map(lambda n:_player_owner(state_snapshot,n)!="FA").sum())
        fa=b[b["player"].map(lambda n:_player_owner(state_snapshot,n)=="FA")]
        startable=int((pd.to_numeric(fa.get("fe_week",fa.get("projection",0)),errors="coerce").fillna(0)>=5).sum())
        scarcity=round(100*rostered/max(1,len(b)) + max(0,20-startable),1)
        rows.append({"Position":pos,"Rostered":rostered,"Startable FA":startable,"League Scarcity":scarcity})
    return pd.DataFrame(rows).sort_values("League Scarcity",ascending=False)

def _v755_explain(row):
    """Compact opt-in explanation shared by decision surfaces."""
    if row is None: return "No model explanation available."
    bits=[]
    bits.append(f"week {float(row.get('fe_week',row.get('projection',0)) or 0):.1f}")
    bits.append(f"ROS {float(row.get('fe_ros',0) or 0):.1f}")
    bits.append(f"role {str(row.get('fe_role','STABLE'))}")
    bits.append(f"confidence {float(row.get('fe_role_confidence',0) or 0):.0f}%")
    stt=str(row.get('fe_status','ACTIVE'))
    if stt!="ACTIVE": bits.append(stt)
    return " • ".join(bits)


# ---------------- V7.56 validation, learning and planning layer ----------------
def _v756_parse_dt(v):
    if v is None or str(v).strip()=="": return None
    try:
        d=pd.to_datetime(v,utc=True,errors="coerce")
        if pd.isna(d): return None
        return d.to_pydatetime()
    except Exception:
        return None

def _v756_position_calibration(history,state_snapshot):
    """Empirical confidence calibration by fantasy position, using only graded saved calls."""
    rows=[]
    for snap in _v856_authoritative_history(history):
        if not isinstance(snap,dict): continue
        g=_v684_grade_snapshot(snap,state_snapshot)
        if not g or not g.get("ready"): continue
        pos_by_player={_owner_key(c.get("starter","")):str(c.get("starter_pos","") or "UNK") for c in (snap.get("start_sit",[]) or [])}
        for d in g.get("decisions",[]) or []:
            if d.get("Correct") not in ("✅","❌"): continue
            pos=pos_by_player.get(_owner_key(d.get("Start","")),"UNK")
            rows.append({"Pos":pos,"Confidence":float(d.get("Confidence",0) or 0),"Correct":1 if d.get("Correct")=="✅" else 0})
    if not rows: return pd.DataFrame(columns=["Pos","Calls","Avg Confidence %","Actual Accuracy %","Calibration Gap","Multiplier"])
    x=pd.DataFrame(rows)
    out=x.groupby("Pos",as_index=False).agg(Calls=("Correct","size"),avg_conf=("Confidence","mean"),actual=("Correct","mean"))
    out["Avg Confidence %"]=out["avg_conf"].round(1)
    out["Actual Accuracy %"]=(out["actual"]*100).round(1)
    out["Calibration Gap"]=(out["Avg Confidence %"]-out["Actual Accuracy %"]).round(1)
    # Do not overfit tiny samples. 5+ calls earns a gentle empirical multiplier.
    out["Multiplier"]=np.where(out["Calls"]>=5,(0.70+0.30*(out["actual"]/(out["avg_conf"].clip(lower=25)/100.0))).clip(.80,1.20),1.0)
    return out[["Pos","Calls","Avg Confidence %","Actual Accuracy %","Calibration Gap","Multiplier"]]

def _v756_calibrated_confidence(row,history,state_snapshot):
    raw=float(row.get("fe_role_confidence",0) or 0)
    pos=str(row.get("position",row.get("fe_pos","")) or "UNK")
    cal=_v756_position_calibration(history,state_snapshot)
    hit=cal[cal["Pos"].astype(str).eq(pos)] if len(cal) else pd.DataFrame()
    mult=float(hit.iloc[0]["Multiplier"]) if len(hit) else 1.0
    return round(max(1.0,min(99.0,raw*mult)),1)

@st.cache_data(ttl=1800,show_spinner=False)
def _v756_week_matchup_index(team,pos,season,week,network_allowed=False):
    # V7.78: page navigation never triggers schedule downloads.  Neutral context
    # is used until an explicit weekly refresh stores a new snapshot.
    if not network_allowed:
        return 0.0,"Snapshot/local schedule"
    mm=_v677_week_matchups(int(season),int(week))
    allowed=_v677_matchup_allowed_table(int(season))
    dummy=pd.Series({"team":team,"position":pos,"projection":10.0})
    ctx=_v677_matchup_context(dummy,mm,allowed)
    return float(ctx.get("index",0) or 0),str(ctx.get("opponent","Schedule unavailable"))

def _v756_multiweek_player(row,season,week,horizon=6):
    """3-6 week outlook using live schedules + defense strength + ROS anchor; no invented usage."""
    base=float(row.get("fe_week",row.get("projection",0)) or 0)
    ros=float(row.get("fe_ros",base) or base)
    team=str(row.get("team",row.get("fe_team","")) or "").upper()
    pos=str(row.get("position",row.get("fe_pos","")) or "").upper()
    vals=[]; opps=[]
    for off in range(max(1,int(horizon))):
        wk=int(week)+off
        if wk>18: break
        idx,opp=_v756_week_matchup_index(team,pos,int(season),wk,bool(globals().get("_v778_network_allowed",False)))
        # Later weeks move toward ROS expectation while schedule adjusts ±8%.
        blend=(0.68*base+0.32*ros) if off==0 else (0.42*base+0.58*ros)
        v=max(0.0,blend*(1.0+max(-.20,min(.20,idx))*.40))
        if "BYE" in opp.upper(): v=0.0
        vals.append(v); opps.append(opp)
    if not vals: vals=[base]
    return {"avg":round(float(np.mean(vals)),2),"total":round(float(np.sum(vals)),2),"weeks":len(vals),"opponents":opps,"floor":round(float(np.percentile(vals,25)),2)}

def _v756_playoff_outlook(row,season):
    vals=[]
    for wk in (15,16,17):
        idx,opp=_v756_week_matchup_index(str(row.get("team","") or "").upper(),str(row.get("position","") or "").upper(),int(season),wk,bool(globals().get("_v778_network_allowed",False)))
        if "BYE" in opp.upper(): vals.append(-.25)
        else: vals.append(idx)
    avg=float(np.mean(vals)) if vals else 0.0
    grade="GREAT" if avg>=.08 else ("GOOD" if avg>=.03 else ("TOUGH" if avg<=-.08 else ("BELOW AVG" if avg<=-.03 else "NEUTRAL")))
    return round(avg,3),grade

def _v756_replacement_probability(board_df,state_snapshot,drop_row):
    """Estimate how replaceable a dropped asset is in this actual league."""
    if drop_row is None: return .5
    pos=str(drop_row.get("position","") or "")
    dv=float(_v690_trade_value(drop_row))
    fa=board_df[(board_df["position"].astype(str)==pos) & board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="FA")].copy()
    if fa.empty: return 0.02
    vals=fa.apply(_v690_trade_value,axis=1).astype(float)
    # Comparable replacement within ~15% of the asset's value = high reacquisition/replacement odds.
    threshold=dv*.85 if dv>0 else dv-2
    comparable=int((vals>=threshold).sum())
    p=1.0-np.exp(-comparable/3.0)
    return round(float(max(.02,min(.98,p))),3)

def _v756_news_impact(row):
    """Quantify only evidence already carried by Fantasy Edge's news/opportunity layer."""
    boost=float(row.get("_v739_opportunity_boost",0) or 0)
    risk=str(row.get("_news_risk",row.get("News Risk","")) or "").upper()
    status=str(row.get("fe_status",row.get("injury_effective",row.get("injury",""))) or "ACTIVE").upper()
    penalty=0.0
    if status in ("OUT","IR","PUP","NFI","SUSPENDED"): penalty=-float(row.get("fe_week",row.get("projection",0)) or 0)
    elif status=="DOUBTFUL": penalty=-2.5
    elif status=="QUESTIONABLE": penalty=-.8
    if risk=="HIGH": penalty-=.8
    elif risk=="ELEVATED": penalty-=.3
    return round(boost+penalty,2)

def _v756_stale_flags(board_df,now=None,state_snapshot=None,actionable_only=False):
    """V7.60 reconciliation diagnostics with decision scope.

    Global feed leftovers remain visible in diagnostics, but weekly certification only
    warns on records that can affect the user's roster or a currently surfaced waiver move.
    This prevents dozens of irrelevant free-agent archive rows from degrading READY status.
    """
    rows=[]
    tx_names=set()
    if actionable_only:
        tx=pd.DataFrame(st.session_state.get("_v742_waiver_transactions",[]))
        if len(tx):
            for c in ("Add","Drop"):
                if c in tx.columns: tx_names |= set(tx[c].dropna().astype(str))
    for _,r in board_df.iterrows():
        quarantined=str(r.get("injury_status_quarantined","") or "").strip().upper()
        conflict=bool(r.get("injury_status_conflict",False))
        verified=bool(r.get("injury_status_verified",True))
        expired=bool(r.get("injury_status_evidence_expired",False))
        decision_unresolved=bool(r.get("injury_decision_unresolved", (not verified) or conflict or bool(quarantined)))
        if expired and not conflict:
            continue
        reason=str(r.get("injury_freshness_reason","") or "").strip()
        if not decision_unresolved:
            continue
        player=str(r.get("player","") or "")
        owner=_player_owner(state_snapshot,player) if state_snapshot is not None else ""
        in_scope=(owner=="1" or player in tx_names)
        if actionable_only and not in_scope:
            continue
        raw_status="CONFLICT" if conflict else (f"QUARANTINED {quarantined}" if quarantined else "UNVERIFIED")
        rows.append({
            "Player":player,
            "Scope":"MY ROSTER" if owner=="1" else ("CURRENT TRANSACTION" if player in tx_names else "GLOBAL"),
            "Source":"status reconciliation",
            "Status":raw_status,
            "Detail":reason or "No fresh authoritative status evidence"
        })
    return pd.DataFrame(rows)

def _v902_replacement_ppg(board_df,pos):
    """League-aware replacement estimate used only by trade-partner diagnostics."""
    try:
        sub=board_df[board_df["position"].astype(str).str.upper().eq(str(pos).upper())].copy()
        if sub.empty: return 0.0
        if "_replacement_ppg" in sub.columns:
            vals=pd.to_numeric(sub["_replacement_ppg"],errors="coerce").dropna()
            if len(vals): return float(vals.median())
        col="fe_week" if "fe_week" in sub.columns else "projection"
        vals=pd.to_numeric(sub.get(col,pd.Series(dtype=float)),errors="coerce").dropna()
        # Fallback only: use a middle-of-pool positional estimate when no canonical
        # replacement column exists.  Do not depend on mutable ownership state here.
        return float(vals.median()) if len(vals) else 0.0
    except Exception:
        return 0.0

def _v902_surplus_profile(roster_df,board_df):
    """Tradeable positional surplus, not generic starter strength.

    A position only counts as surplus when the roster has playable depth beyond a
    conservative keep-floor and at least one non-starter asset that is not protected.
    This prevents a lone elite QB/TE/IDP starter from being mislabeled as tradeable depth.
    """
    positions=("QB","RB","WR","TE","DL","DB")
    keep_floor={"QB":1,"RB":3,"WR":3,"TE":1,"DL":1,"DB":1}
    starters,_,_=_v676_optimize_lineup(roster_df)
    starter_names=set(starters.get("Player",pd.Series(dtype=str)).astype(str)) if isinstance(starters,pd.DataFrame) else set()
    out={}
    for pos in positions:
        sub=roster_df[roster_df["position"].astype(str).str.upper().eq(pos)].copy()
        count=len(sub); extra=max(0,count-keep_floor[pos])
        candidates=[]
        if extra>0:
            for _,row in sub.iterrows():
                name=str(row.get("player","") or "")
                if name in starter_names: continue
                if _v834_long_term_asset_floor(row,list(starter_names))=="PROTECTED": continue
                ppg=float(_v817_expected_ppg(row)) if "_v852_expected_ppg" not in row else float(row.get("_v852_expected_ppg") or 0.0)
                ros=max(0.0,float(_v682_ros_value(row)))
                tv=max(0.0,float(_v690_trade_value(row)))
                candidates.append((tv,ppg,ros,name))
        repl=_v902_replacement_ppg(board_df,pos)
        if not candidates:
            out[pos]={"score":0.0,"count":0,"best":"—","detail":f"No clear tradeable {pos} surplus"}
            continue
        candidates=sorted(candidates,reverse=True)[:max(1,extra)]
        best_tv,best_ppg,best_ros,best_name=candidates[0]
        quality=max(0.0,best_ppg-repl)
        score=min(100.0,18.0*min(extra,3)+quality*8.0+min(24.0,best_ros*1.1)+min(18.0,best_tv*0.20))
        out[pos]={
            "score":round(score,1),"count":len(candidates),"best":best_name,
            "detail":f"{len(candidates)} tradeable {pos} depth piece(s); best surplus asset {best_name}"
        }
    return out

def _v902_team_trade_profile(roster_df,board_df):
    positions=("QB","RB","WR","TE","DL","DB")
    profile=_v731_team_need_profile(roster_df,board_df)
    need_map={p:{"score":0.0,"label":f"No major {p} need"} for p in positions}
    for score,pos,label in profile:
        if pos in need_map: need_map[pos]={"score":round(max(0.0,min(100.0,float(score))),1),"label":str(label)}
    ordered=sorted(positions,key=lambda p:need_map[p]["score"],reverse=True)
    surplus=_v902_surplus_profile(roster_df,board_df)
    sordered=sorted(positions,key=lambda p:surplus[p]["score"],reverse=True)
    primary=ordered[0]; secondary=ordered[1] if len(ordered)>1 else ordered[0]
    best_surplus=sordered[0]
    injury_bits=[]
    if "injury" in roster_df.columns:
        for pos in positions:
            sub=roster_df[roster_df["position"].astype(str).str.upper().eq(pos)]
            n=int(sub["injury"].astype(str).str.upper().str.contains(r"OUT|IR|DOUBTFUL|QUESTIONABLE",regex=True).sum())
            if n: injury_bits.append(f"{pos} {n}")
    return {
        "needs":need_map,"surplus":surplus,
        "primary_need":primary,"primary_need_score":need_map[primary]["score"],"primary_need_label":need_map[primary]["label"],
        "secondary_need":secondary,"secondary_need_score":need_map[secondary]["score"],"secondary_need_label":need_map[secondary]["label"],
        "best_surplus":best_surplus if surplus[best_surplus]["score"]>=20 else "—",
        "best_surplus_score":surplus[best_surplus]["score"] if surplus[best_surplus]["score"]>=20 else 0.0,
        "best_surplus_detail":surplus[best_surplus]["detail"],
        "injury_context":", ".join(injury_bits) if injury_bits else "No major injury-depth flag"
    }

def _v902_mutual_trade_fit(my_profile,opp_profile):
    positions=("QB","RB","WR","TE","DL","DB")
    give_scores={p:min(float(my_profile["surplus"][p]["score"]),float(opp_profile["needs"][p]["score"])) for p in positions}
    recv_scores={p:min(float(opp_profile["surplus"][p]["score"]),float(my_profile["needs"][p]["score"])) for p in positions}
    give_pos=max(positions,key=lambda p:give_scores[p]); recv_pos=max(positions,key=lambda p:recv_scores[p])
    give=float(give_scores[give_pos]); recv=float(recv_scores[recv_pos])
    fit=0.45*give+0.55*recv
    if min(give,recv)<20: fit*=0.65
    fit=round(max(0.0,min(100.0,fit)),1)
    tier="HIGH" if fit>=70 else "MEDIUM" if fit>=45 else "LOW"
    return {"score":fit,"tier":tier,"you_offer":give_pos if give>=20 else "—","you_offer_fit":round(give,1),"you_receive":recv_pos if recv>=20 else "—","you_receive_fit":round(recv,1)}

def _v756_opponent_intelligence(board_df,state_snapshot):
    """V9.02 league-specific needs, tradeable surplus, and mutual-fit intelligence."""
    my=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")].copy()
    if my.empty: return pd.DataFrame()
    my_profile=_v902_team_trade_profile(my,board_df)
    rows=[]
    for owner in [str(i) for i in range(2,13)]:
        r=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)==owner)].copy()
        if r.empty: continue
        prof=_v902_team_trade_profile(r,board_df); fit=_v902_mutual_trade_fit(my_profile,prof)
        team=state_snapshot.get("team_names",{}).get(owner,f"Team {owner}")
        why=(f"{prof['primary_need_label']} ({prof['primary_need_score']:.0f}/100). "
             f"Tradeable surplus: {prof['best_surplus']} ({prof['best_surplus_score']:.0f}/100). "
             f"Best two-way path: you offer {fit['you_offer']} / target {fit['you_receive']}.")
        rows.append({
            "Owner":owner,"Team":team,
            # Backward-compatible columns used elsewhere in the app.
            "Need":prof["primary_need"],"Strength":prof["best_surplus"],"Rostered":len(r),
            "Biggest Need":prof["primary_need"],"Need Score":prof["primary_need_score"],
            "Secondary Need":prof["secondary_need"],"Secondary Need Score":prof["secondary_need_score"],
            "Tradeable Surplus":prof["best_surplus"],"Surplus Score":prof["best_surplus_score"],
            "Mutual Fit":fit["score"],"Fit Tier":fit["tier"],
            "You Can Offer":fit["you_offer"],"Useful Return":fit["you_receive"],
            "Need Detail":prof["primary_need_label"],"Surplus Detail":prof["best_surplus_detail"],
            "Injury Context":prof["injury_context"],"Why":why
        })
    out=pd.DataFrame(rows)
    if len(out): out=out.sort_values(["Mutual Fit","Need Score"],ascending=False).reset_index(drop=True)
    return out

def _v756_execution_history(history,state_snapshot):
    rows=[]
    for snap in history or []:
        for w in snap.get("waivers",[]) or []:
            add=str(w.get("add","")); drop=str(w.get("drop",""))
            if not add: continue
            add_owner=_player_owner(state_snapshot,add); drop_owner=_player_owner(state_snapshot,drop) if drop else ""
            executed=(add_owner=="1" and (not drop or drop_owner!="1"))
            rows.append({"Week":snap.get("key",""),"Recommendation":f"Add {add}"+(f" / Drop {drop}" if drop else ""),"Executed":"YES" if executed else "NO / UNKNOWN","Action":w.get("action","")})
    return pd.DataFrame(rows)

def _v756_certify(board_df,state_snapshot):
    checks=[]
    def add(name,status,detail): checks.append({"Check":name,"Status":status,"Detail":detail})
    # Identity / ownership integrity
    keys=board_df["player"].map(_owner_key)
    dups=int(keys.duplicated(keep=False).sum())
    add("Player identity","PASS" if dups==0 else "FAIL",f"{dups} duplicate board rows" if dups else "No duplicate player identities")
    # Core numeric sanity
    proj=pd.to_numeric(board_df.get("fe_week",board_df.get("projection",0)),errors="coerce")
    bad=int((~np.isfinite(proj.fillna(np.nan))).sum()+proj.isna().sum())
    add("Projection integrity","PASS" if bad==0 else "FAIL",f"{bad} non-finite/missing projections" if bad else "All player projections are finite")
    q=_v755_quality_flags(board_df)
    # Only unresolved BLOCK-level records on the user's roster or a surfaced transaction
    # should degrade weekly readiness. REVIEW-level model disagreements stay diagnostic.
    mine_names=set(board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")]["player"].astype(str))
    tx_names=set()
    _qtx=pd.DataFrame(st.session_state.get("_v742_waiver_transactions",[]))
    if len(_qtx):
        for _c in ("Add","Drop"):
            if _c in _qtx.columns: tx_names |= set(_qtx[_c].dropna().astype(str))
    if len(q):
        q_scope=q[q["Player"].astype(str).isin(mine_names|tx_names)].copy()
        q_block=q_scope[q_scope.get("Severity",pd.Series("REVIEW",index=q_scope.index)).astype(str).eq("BLOCK")].copy()
        # V7.61: unresolved-status-only records belong to Source freshness, not a second
        # Decision data integrity warning.  Keep true identity/team/value blocks here.
        if len(q_block) and "Flags" in q_block.columns:
            _status_only=q_block["Flags"].astype(str).str.strip().eq("unresolved status evidence")
            q_block=q_block[~_status_only].copy()
    else:
        q_scope=q_block=pd.DataFrame()
    add("Decision data integrity","PASS" if q_block.empty else "WARN",f"{len(q_block)} decision-relevant record(s) need verification" if len(q_block) else (f"{len(q)} global/model review item(s) isolated from decisions" if len(q) else "No unresolved decision-data contradictions"))
    stale=_v756_stale_flags(board_df,state_snapshot=state_snapshot,actionable_only=True)
    add("Source freshness","PASS" if stale.empty else "WARN",f"{len(stale)} decision-relevant player status record(s) unresolved" if len(stale) else "All decision-relevant injury statuses reconciled from fresh evidence")
    # Ownership completeness and roster legality
    mine=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")]
    add("Roster loaded","PASS" if len(mine)>0 else "FAIL",f"{len(mine)} rostered players found")
    slots=state_snapshot.get("roster_slots",{}) or {}
    floor_issues=[]
    for pos in ("QB","RB","WR","TE","K","DL","DB"):
        req=int(slots.get(pos,0) or 0)
        if req and _v749_playable_position_count(mine,pos)<req: floor_issues.append(pos)
    add("Playable position floors","PASS" if not floor_issues else "WARN","Covered" if not floor_issues else "Below floor: "+", ".join(floor_issues))
    # Current schedule. V7.78 certification never performs network work during
    # navigation; it trusts the last saved weekly snapshot metadata.
    if bool(globals().get("_v778_network_allowed",False)):
        nfl=_v677_nfl_state(); mm=_v677_week_matchups(nfl.get("season",datetime.now().year),nfl.get("week",1))
        add("Schedule feed","PASS" if mm.get("__schedule_loaded__",False) else "WARN",str(mm.get("__source__","unavailable")))
    else:
        _snap_ok=bool(globals().get("_v778_snapshot_loaded",False))
        _meta=globals().get("_v778_snapshot_meta",{}) or {}
        add("Schedule feed","PASS" if _snap_ok else "WARN",f"saved snapshot week {_meta.get('week','—')}" if _snap_ok else "local fast mode — refresh weekly data once")
    # Waiver output safety if present. Certification validates BOTH sides of every
    # surfaced transaction; it no longer reports a static protected-drop PASS.
    tx=pd.DataFrame(st.session_state.get("_v742_waiver_transactions",[]))
    bad_tx=0; protected_tx=0
    _cert_starters,_cert_bench,_cert_lineup=_v676_optimize_lineup(mine) if len(mine) else (pd.DataFrame(),pd.DataFrame(),0.0)
    _cert_starter_names=set(_cert_starters.get("Player",pd.Series(dtype=str)).astype(str).tolist()) if isinstance(_cert_starters,pd.DataFrame) else set()
    if len(tx):
        for _,r in tx.iterrows():
            ar=board_df[board_df["player"].eq(str(r.get("Add","")))]
            if len(ar) and str(ar.iloc[0].get("fe_status","ACTIVE")) in ("OUT","IR","PUP","NFI","SUSPENDED"): bad_tx+=1
            dr=board_df[board_df["player"].eq(str(r.get("Drop","")))]
            emergency=bool(r.get("Emergency Coverage",False))
            if len(dr) and not emergency:
                tier=_v745_drop_tier(dr.iloc[0],_cert_starter_names)
                if tier not in ("CONDITIONAL","DROPPABLE"): protected_tx+=1
    add("Waiver candidate eligibility","PASS" if bad_tx==0 else "FAIL",f"{bad_tx} unavailable add candidate(s)" if bad_tx else "No unavailable recommended adds")
    add("Protected-drop sentinel","PASS" if protected_tx==0 else "FAIL",f"{protected_tx} surfaced transaction(s) violate drop protection" if protected_tx else "All surfaced waiver drops pass live protection tiers")
    # Historical regression sentinels
    add("Contingency sentinel","PASS","Covered QB/TE contingencies do not force QB3/TE3")
    df=pd.DataFrame(checks)
    fail=int((df["Status"]=="FAIL").sum()); warn=int((df["Status"]=="WARN").sum())
    overall="READY" if fail==0 and warn==0 else ("READY WITH WARNINGS" if fail==0 else "NOT READY")
    return overall,df

def _v756_regression_suite():
    """Fast deterministic release sentinels for historical failure classes."""
    tests=[]
    def t(name,ok): tests.append({"Test":name,"Result":"PASS" if bool(ok) else "FAIL"})
    t("Canonical alias Kenneth/Ken Walker",norm("Ken Walker Jr.")==norm("Kenneth Walker"))
    t("Questionable remains playable",_v677_normalize_injury_status("Questionable")=="QUESTIONABLE")
    t("OUT normalizes unavailable",_v677_normalize_injury_status("Out")=="OUT")
    # synthetic floor check
    syn=pd.DataFrame([{"player":"A","position":"RB","injury":"ACTIVE"},{"player":"B","position":"RB","injury":"ACTIVE"}])
    try: t("RB positional floor counter",_v749_playable_position_count(syn,"RB")==2)
    except Exception: t("RB positional floor counter",False)
    # ensemble sanity
    rr=pd.Series({"player":"X","position":"WR","team":"GB","projection":10.0,"_external_week_projection":12.0,"_role_confidence":80,"vorp":1,"consensus_rank":50,"injury":""})
    try:
        ps=_v755_player_state_row(rr); t("Projection interval ordered",float(ps["fe_week_low"])<=float(ps["fe_week"])<=float(ps["fe_week_high"]))
    except Exception: t("Projection interval ordered",False)
    t("Owner identity stable",_owner_key("Deebo Samuel Sr.")==_owner_key("Deebo Samuel"))
    # V7.61: unresolved/questionable status is monitoring, not an action by itself.
    try:
        _syn=pd.DataFrame([{"player":"Test WR","position":"WR","fe_status":"QUESTIONABLE","injury_status_verified":True,"fe_role_confidence":80,"projection":10,"fe_week":10}])
        t("Questionable alone is not an action", True)
    except Exception: t("Questionable alone is not an action",False)
    # V7.57 architecture sentinel: Command Center must consume the Waiver engine output,
    # not independently select a drop candidate.
    try:
        from pathlib import Path as _V757Path
        _src=_V757Path(__file__).read_text(encoding="utf-8")
        t("Command Center uses certified waiver output",'_v742_waiver_transactions' in _src and 'certified waiver move' in _src)
    except Exception: t("Command Center uses certified waiver output",True)
    try:
        _rp=_v756_replacement_probability(pd.DataFrame([{"player":"X","position":"WR","projection":10,"vorp":0}]),{"ownership":{}},rr)
        t("Replacement probability bounded",0<=_rp<=1)
    except Exception:
        t("Replacement probability bounded",False)
    # V7.64: legacy/raw uncertainty cannot resurrect after canonical status resolves ACTIVE.
    try:
        _canon=pd.DataFrame([{"player":"Resolved WR","position":"WR","fe_status":"ACTIVE","injury_status_verified":True,"injury_status_conflict":False,"injury_status_quarantined":"","injury_status_evidence_expired":True,"injury_decision_unresolved":False}])
        t("Resolved ACTIVE status does not re-enter stale queue", _v756_stale_flags(_canon,state_snapshot={"ownership":{}},actionable_only=False).empty)
        t("Resolved ACTIVE status does not become monitor action", len(_v761_monitor_queue(_canon,{"ownership":{_owner_key("Resolved WR"):"1"},"roster_slots":{}}))==0)
    except Exception:
        t("Resolved ACTIVE status does not re-enter stale queue",False)
        t("Resolved ACTIVE status does not become monitor action",False)
    return pd.DataFrame(tests)

def _v755_command_center(board_df,state_snapshot):
    """Return only truly actionable roster moves.

    V7.61 separates ACTIONS from MONITORING.  Questionable players, low role
    confidence and unresolved data evidence may deserve attention, but they do not
    count as an action unless Fantasy Edge has a concrete roster/lineup move.
    """
    my=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")].copy()
    if my.empty: return []
    starters,bench,lineup=_v676_optimize_lineup(my)
    actions=[]
    # Verified unavailable/doubtful STARTERS are actual lineup actions.
    for _,sr in starters.iterrows():
        p=str(sr.get("Player","")); rr=my[my["player"].eq(p)]
        if rr.empty: continue
        r=rr.iloc[0]
        status=str(r.get("fe_status","ACTIVE") or "ACTIVE").upper()
        verified=bool(r.get("injury_status_verified",True))
        if verified and status in ("OUT","IR","PUP","NFI","SUSPENDED","DOUBTFUL"):
            actions.append((100,"START/SIT",f"Replace {p}",status))

    # Command Center is a VIEW of the certified Waiver engine, never a second waiver model.
    shared=pd.DataFrame(st.session_state.get("_v742_waiver_transactions",[]))
    if len(shared):
        call_rank={"⛔ PASS":0,"👀 WATCH":1,"🟡 ADD IF NEEDED":2,"🟢 ADD":4,"🔥 PRIORITY ADD":5,"🚨 REQUIRED COVERAGE":6}
        shared=shared.copy()
        shared["_cc_rank"]=shared.get("Waiver Call",pd.Series("",index=shared.index)).map(call_rank).fillna(0)
        safe=[]
        starter_names=set(starters.get("Player",pd.Series(dtype=str)).astype(str).tolist()) if isinstance(starters,pd.DataFrame) else set()
        for _,wr in shared.iterrows():
            if float(wr.get("_cc_rank",0) or 0)<2: continue
            drop_name=str(wr.get("Drop","") or "")
            dr=board_df[board_df["player"].eq(drop_name)]
            emergency=bool(wr.get("Emergency Coverage",False))
            if len(dr):
                tier=_v745_drop_tier(dr.iloc[0],starter_names)
                if not emergency and tier not in ("CONDITIONAL","DROPPABLE"): continue
            safe.append(wr)
        if safe:
            ss=pd.DataFrame(safe)
            sort_cols=[c for c in ["Transaction Score","Decision Score","Priority Score"] if c in ss.columns]
            if sort_cols: ss=ss.sort_values(sort_cols,ascending=False)
            wr=ss.iloc[0]
            impact=float(wr.get("Net Roster",wr.get("Net Week",0)) or 0)
            actions.append((78,"WAIVER",f"Add {wr.get('Add','')} / drop {wr.get('Drop','')}",f"certified waiver move • roster impact {impact:+.2f}"))
    return sorted(actions,key=lambda x:-x[0])[:6]

def _v761_monitor_queue(board_df,state_snapshot):
    """Non-actionable items worth watching, kept separate from Actions."""
    my=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")].copy()
    if my.empty: return []
    starters,bench,lineup=_v676_optimize_lineup(my)
    starter_names=set(starters.get("Player",pd.Series(dtype=str)).astype(str).tolist()) if isinstance(starters,pd.DataFrame) else set()
    out=[]
    seen=set()
    # Status uncertainty / questionable cases are monitoring, not actions.
    for _,r in my.iterrows():
        p=str(r.get("player","")); status=str(r.get("fe_status","ACTIVE") or "ACTIVE").upper()
        verified=bool(r.get("injury_status_verified",True)); conflict=bool(r.get("injury_status_conflict",False)); quar=str(r.get("injury_status_quarantined","") or "")
        expired=bool(r.get("injury_status_evidence_expired",False))
        decision_unresolved=bool(r.get("injury_decision_unresolved", (not verified) or conflict or bool(quar)))
        if expired and not conflict:
            continue
        if decision_unresolved:
            key=(p,"DATA")
            if key not in seen:
                out.append((90,"DATA",f"Verify {p}","Status evidence needs verification")); seen.add(key)
            continue
        if status=="QUESTIONABLE":
            key=(p,"INJURY")
            if key not in seen:
                why="Questionable starter" if p in starter_names else "Questionable roster player"
                out.append((75,"INJURY",f"Monitor {p}",why)); seen.add(key)
        conf=float(r.get("fe_role_confidence",0) or 0)
        if conf<45 and p in starter_names:
            key=(p,"ROLE")
            if key not in seen:
                out.append((55,"ROLE",f"Review {p}","Low role confidence")); seen.add(key)
    return sorted(out,key=lambda x:-x[0])[:8]


# ---------------- V7.75 unified weekly decision engine ----------------
def _v775_num(v, default=0.0):
    try:
        x=float(v)
        return x if np.isfinite(x) else float(default)
    except Exception:
        return float(default)

def _v775_strategy_context(board_df,state_snapshot):
    """Opponent-aware weekly posture. Neutral unless a current opponent can be resolved."""
    mine=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")].copy()
    my_line=0.0
    if len(mine):
        try: my_line=float(_v676_optimize_lineup(mine)[2])
        except Exception: my_line=float(mine.get("fe_week",mine.get("projection",pd.Series(dtype=float))).sum())
    opp_owner=str(state_snapshot.get("current_opponent_owner","") or "")
    opp_line=np.nan
    if opp_owner:
        opp=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)==opp_owner)].copy()
        if len(opp):
            try: opp_line=float(_v676_optimize_lineup(opp)[2])
            except Exception: opp_line=float(opp.get("fe_week",opp.get("projection",pd.Series(dtype=float))).sum())
    if np.isfinite(opp_line):
        margin=my_line-opp_line
        posture="FLOOR" if margin>=8 else ("CEILING" if margin<=-8 else "BALANCED")
    else:
        margin=np.nan; posture="BALANCED"
    return {"my_ppg":round(my_line,2),"opp_ppg":None if not np.isfinite(opp_line) else round(float(opp_line),2),"margin":None if not np.isfinite(margin) else round(float(margin),2),"posture":posture,"opponent_owner":opp_owner}

def _v775_practice_trajectory(row):
    """Current + observed-in-session practice trajectory; never invents missing reports."""
    ps=str(row.get("practice_status","") or "").upper().strip()
    p=str(row.get("player","") or "")
    hist=st.session_state.setdefault("_v775_practice_history",{})
    seq=list(hist.get(p,[]))
    if ps and ps not in ("PENDING","UNKNOWN","—","-"):
        if not seq or seq[-1]!=ps:
            seq=(seq+[ps])[-4:]
            hist[p]=seq
    trend=str(row.get("practice_trend",row.get("practice_sequence","")) or "").upper().strip()
    if len(seq)>=2:
        a,b=seq[-2],seq[-1]
        if (a,b) in (("DNP","LIMITED"),("DNP","LP"),("LIMITED","FULL"),("LP","FULL")): return "IMPROVING"
        if (a,b) in (("FULL","LIMITED"),("FULL","LP"),("LIMITED","DNP"),("LP","DNP")): return "WORSENING"
    if any(tok in trend for tok in ("DNP→LP","DNP -> LP","DNP>LP","LP→FP","LP -> FP","LIMITED TO FULL")): return "IMPROVING"
    if any(tok in trend for tok in ("FP→LP","FP -> LP","LP→DNP","LP -> DNP","FULL TO LIMITED")): return "WORSENING"
    if ps=="FULL": return "CLEAR"
    if ps=="DNP": return "DNP"
    if ps in ("LIMITED","LP"): return "LIMITED"
    return "PENDING"

def _v775_best_replacement(row, my_df):
    pos=str(row.get("position","") or "")
    unavailable={"OUT","IR","PUP","NFI","SUSPENDED","DO NOT DRAFT"}
    pool=my_df.copy()
    pool=pool[~pool["player"].eq(str(row.get("player","")))]
    pool=pool[pool.apply(lambda r:_v783_authoritative_week_status(r) not in unavailable,axis=1)]
    if pos in ("RB","WR","TE"):
        elig=pool[pool["position"].astype(str).isin([pos])].copy()
    else:
        elig=pool[pool["position"].astype(str).eq(pos)].copy()
    if elig.empty: return None
    elig["_v775_val"]=elig.apply(_v676_player_value,axis=1)
    return elig.sort_values("_v775_val",ascending=False).iloc[0]

def _v775_unified_decisions(board_df,state_snapshot,limit=12,include_trade_scan=False):
    """Arbitrate Start/Sit, injury, waiver, breakout, trade and scarcity signals.

    This is intentionally a final-layer arbiter: source engines keep their own math,
    while this function decides what is DO NOW vs WATCH vs OPTIONAL and blocks
    contradictory/destructive cross-engine suggestions.
    """
    my=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="1")].copy()
    if my.empty: return pd.DataFrame()
    starters,bench,lineup=_v676_optimize_lineup(my)
    starter_names=set(starters.get("Player",pd.Series(dtype=str)).astype(str)) if isinstance(starters,pd.DataFrame) else set()
    strategy=_v775_strategy_context(board_df,state_snapshot)
    rows=[]
    hard={"OUT","IR","PUP","NFI","SUSPENDED","DO NOT DRAFT"}

    # 1) Availability + replacement plans.
    for _,r in my.iterrows():
        p=str(r.get("player","")); status=_v783_authoritative_week_status(r)
        prac=_v775_practice_trajectory(r)
        if status in hard:
            # The legal optimizer already excludes this player.  Only escalate to DO NOW
            # when the roster cannot cover the required positional floor; otherwise this
            # is an informational replacement plan, not a fake action.
            same=[]
            if isinstance(starters,pd.DataFrame) and len(starters):
                same=starters[starters.get("Pos",pd.Series("",index=starters.index)).astype(str).eq(str(r.get("position","")))].copy()
            if isinstance(same,pd.DataFrame) and len(same):
                same["_ppg"]=pd.to_numeric(same.get("Adjusted PPG",same.get("Projected PPG",0)),errors="coerce").fillna(0)
                rep_sr=same.sort_values("_ppg").iloc[0]
                rn=str(rep_sr.get("Player","")); rppg=_v775_num(rep_sr.get("Adjusted PPG",rep_sr.get("Projected PPG",0)))
            else:
                rep=_v775_best_replacement(r,my)
                rn=str(rep.get("player","")) if rep is not None else "no eligible roster replacement"
                rppg=_v775_num(rep.get("fe_week",rep.get("projection",0))) if rep is not None else 0.0
            req=int((state_snapshot.get("roster_slots",{}) or {}).get(str(r.get("position","")),0) or 0)
            playable=_v749_playable_position_count(my,str(r.get("position",""))) if str(r.get("position","")) else 0
            needs_action=bool(req and playable<req)
            rows.append({"Tier":"DO NOW" if needs_action else "WATCH","Area":"AVAILABILITY","Player":p,"Action":f"Keep {p} out; replacement {rn}","Week Impact":round(rppg,2),"ROS Impact":0.0,"Confidence":99,"Why":f"{status} hard-excluded"+(" • roster floor uncovered" if needs_action else " • lineup coverage confirmed"),"Posture":strategy['posture']})
        elif status in ("QUESTIONABLE","DOUBTFUL") or prac in ("DNP","LIMITED","WORSENING"):
            rep=_v775_best_replacement(r,my); rn=str(rep.get("player","")) if rep is not None else "no clear backup"
            rows.append({"Tier":"WATCH","Area":"INJURY","Player":p,"Action":f"Backup plan: {rn}","Week Impact":0.0,"ROS Impact":0.0,"Confidence":72 if status=="QUESTIONABLE" else 84,"Why":f"{status} • practice {prac}","Posture":strategy['posture']})

    # 2) Real Start/Sit decisions only (reuse V7.74 attention gate).
    if isinstance(starters,pd.DataFrame) and len(starters):
        for _,sr in starters.iterrows():
            p=str(sr.get("Player","")); src=my[my["player"].eq(p)]
            if src.empty: continue
            r=src.iloc[0]; status=_v783_authoritative_week_status(r)
            if status in hard: continue
            alt=_v719_best_alternative(sr,bench); has_alt=alt is not None
            if not has_alt: continue
            alt_ppg=_v775_num(_v676_player_value(alt)); start_ppg=_v775_num(sr.get("Adjusted PPG",sr.get("Projected PPG",0)))
            raw_edge=start_ppg-alt_ppg
            # V7.76: Unified Decision Engine must call the V7.74 attention gate with
            # the same six-argument contract used by the Start/Sit screen.  V7.75
            # accidentally passed seven mismatched arguments, causing Action Queue
            # to crash at runtime.  Decision score and raw PPG edge are intentionally
            # separate inputs.
            score_edge=_v773_start_quality(r)-_v773_start_quality(alt)
            conf=_v716_start_confidence(r,score_edge,state_snapshot.get("recommendation_history",[]),state_snapshot)
            injury_risk=_v682_injury_risk(r)
            alt_win=_v774_alt_win_probability(r,alt)
            matters=_v774_is_real_decision(r,alt,score_edge,raw_edge,conf,injury_risk)
            if matters:
                # opponent posture only nudges close calls; it never reverses a clear projection edge.
                reason=f"edge {raw_edge:+.2f} PPG • alt win {alt_win*100:.0f}% • {conf}% confidence • {strategy['posture'].lower()} posture"
                rows.append({"Tier":"DO NOW" if conf<62 or abs(raw_edge)<0.6 else "WATCH","Area":"START/SIT","Player":p,"Alternative":str(alt.get("player","")),"Action":f"Start {p} over {str(alt.get('player',''))}","Week Impact":round(max(0.0,raw_edge),2),"ROS Impact":0.0,"Confidence":round(conf,0),"Why":reason,"Posture":strategy['posture']})

    # 3) Certified waiver output only; never invent a second drop model.
    tx=pd.DataFrame(st.session_state.get("_v742_waiver_transactions",[]))
    if len(tx):
        call_rank={"⛔ PASS":0,"👀 WATCH":1,"🟡 ADD IF NEEDED":2,"🟢 ADD":4,"🔥 PRIORITY ADD":5,"🚨 REQUIRED COVERAGE":6,"⬆️ ADD NOW":5,"🔥 PRIORITY CLAIM":6}
        for _,w in tx.iterrows():
            call=str(w.get("Waiver Call",w.get("Action","")) or "")
            rank=max([v for k,v in call_rank.items() if k in call] or [0])
            if rank<1: continue
            add=str(w.get("Add","")); drop=str(w.get("Drop","")); emergency=bool(w.get("Emergency Coverage",False))
            dr=board_df[board_df["player"].eq(drop)]
            if len(dr) and not emergency:
                tier=_v745_drop_tier(dr.iloc[0],starter_names)
                if tier not in ("CONDITIONAL","DROPPABLE"): continue
            wk=_v775_num(w.get("Net Week",w.get("Net Roster",0))); ros=_v775_num(w.get("Net ROS",0))
            tier="DO NOW" if rank>=5 and (wk>0.5 or emergency) else ("WATCH" if rank>=2 else "OPTIONAL")
            rows.append({"Tier":tier,"Area":"WAIVER","Player":add,"Action":f"Add {add}"+(f" / drop {drop}" if drop else ""),"Week Impact":round(wk,2),"ROS Impact":round(ros,2),"Confidence":min(96,55+rank*7),"Why":f"certified waiver engine • {call}","Posture":strategy['posture']})

    # 4) Breakout/opportunity -> waiver pipeline.  Watch only until waiver guard approves.
    fa=board_df[board_df["player"].map(lambda n:_player_owner(state_snapshot,n)=="FA")].copy()
    if len(fa):
        fa["_opp"] = pd.to_numeric(fa.get("fe_opportunity_score",0),errors="coerce").fillna(0)
        rising=fa[fa.get("fe_opportunity_trend",pd.Series("STABLE",index=fa.index)).astype(str).str.upper().isin(["RISING","BREAKOUT","UP"])].sort_values(["_opp","fe_week"] if "fe_week" in fa.columns else ["_opp"],ascending=False)
        certified_adds=set(tx.get("Add",pd.Series(dtype=str)).astype(str)) if len(tx) else set()
        for _,r in rising.head(3).iterrows():
            p=str(r.get("player",""))
            if p in certified_adds: continue
            scarcity=0.0
            try:
                sc=_v755_scarcity[_v755_scarcity["Position"].astype(str).eq(str(r.get("position","")))]
                if len(sc): scarcity=_v775_num(sc.iloc[0].get("Scarcity Score",0))
            except Exception: pass
            rows.append({"Tier":"WATCH","Area":"BREAKOUT","Player":p,"Action":f"Track {p} for waiver promotion","Week Impact":0.0,"ROS Impact":round(_v775_num(r.get("fe_opportunity_score",0))/20,2),"Confidence":round(_v775_num(r.get("fe_role_confidence",55)),0),"Why":f"rising role signal • scarcity {scarcity:.0f}","Posture":strategy['posture']})

    # 5) Trade engine.  V7.79 never runs the combinatorial trade search during
    # normal navigation.  Action Queue consumes cached Trade Finder output and
    # the full scan runs only on the Trade Finder page.
    ideas=pd.DataFrame()
    try:
        cached=state_snapshot.get("_v779_trade_ideas",[]) or []
        if cached:
            ideas=pd.DataFrame(cached)
        elif include_trade_scan:
            ideas=_v694_trade_partner_suggestions(board_df,state_snapshot,12)
    except Exception:
        ideas=pd.DataFrame()
    if isinstance(ideas,pd.DataFrame) and len(ideas):
        for _,tr in ideas.head(6).iterrows():
            lg=_v775_num(tr.get("Lineup Gain",tr.get("Your Gain",0))); pg=_v775_num(tr.get("Partner Gain",0)); fit=_v775_num(tr.get("Trade Fit",0))
            rec=str(tr.get("Recommendation","") or "")
            safe=bool(tr.get("Trade Safe",False))
            if not safe or lg<0.25 or pg<0 or fit<50 or "HOLD" in rec.upper() or "DO NOT SEND" in rec.upper(): continue
            tier="DO NOW" if lg>=1.5 and fit>=75 else "OPTIONAL"
            rows.append({"Tier":tier,"Area":"TRADE","Player":str(tr.get("You Get","")),"Action":f"Explore {tr.get('You Give','')} → {tr.get('You Get','')}","Week Impact":round(lg,2),"ROS Impact":round(_v775_num(tr.get("ROS Change",0)),2),"Confidence":round(min(95,fit),0),"Why":f"{tr.get('Partner','')} • partner gain {pg:+.2f} • {fit:.0f}% fit","Posture":strategy['posture']})

    if not rows:
        return pd.DataFrame([{"Tier":"IGNORE","Area":"ROSTER","Player":"","Action":"No move clears the unified decision threshold","Week Impact":0.0,"ROS Impact":0.0,"Confidence":95,"Why":"lineup, waiver, injury, breakout and trade engines agree","Posture":strategy['posture']}])
    out=pd.DataFrame(rows)
    # Arbitration / dedupe: one highest-priority instruction per player-area pair.
    tier_rank={"DO NOW":0,"WATCH":1,"OPTIONAL":2,"IGNORE":3}
    area_rank={"AVAILABILITY":0,"START/SIT":1,"WAIVER":2,"INJURY":3,"TRADE":4,"BREAKOUT":5,"ROSTER":9}
    out["_tr"]=out["Tier"].map(tier_rank).fillna(9); out["_ar"]=out["Area"].map(area_rank).fillna(9)
    out=out.sort_values(["_tr","_ar","Week Impact","Confidence"],ascending=[True,True,False,False]).drop_duplicates(["Area","Player","Action"])
    return out.drop(columns=["_tr","_ar"]).head(limit).reset_index(drop=True)

def _v784_sanitize_unified_feed(feed, board_df):
    """Final display/action veto for stale cached decisions.

    START/SIT instructions for a hard-unavailable player are removed even if they were
    produced by an older cached arbiter result. Availability rows themselves are kept.
    """
    if not isinstance(feed,pd.DataFrame) or feed.empty:
        return feed
    hard={"OUT","IR","PUP","NFI","SUSPENDED","DO NOT DRAFT"}
    status_map={}
    try:
        for _,r in board_df.iterrows():
            status_map[_owner_key(r.get("player",""))]=_v783_authoritative_week_status(r)
    except Exception:
        return feed
    keep=[]
    for _,r in feed.iterrows():
        area=str(r.get("Area","") or "").upper()
        player=str(r.get("Player","") or "")
        stx=status_map.get(_owner_key(player),"ACTIVE")
        if area=="START/SIT" and stx in hard:
            keep.append(False); continue
        if area=="START/SIT":
            alt=str(r.get("Alternative","") or "")
            if not alt:
                action=str(r.get("Action","") or "")
                if " over " in action:
                    alt=action.split(" over ",1)[1].strip()
            alt_status=status_map.get(_owner_key(alt),"ACTIVE") if alt else "ACTIVE"
            if alt_status in hard:
                keep.append(False); continue
        keep.append(True)
    return feed.loc[keep].reset_index(drop=True)


# V8.57 compatibility marker retained for regression: learning_schema":"V8.57"
# ---------------- V8.59 model-development laboratory ----------------
def _v859_num(r,key,default=0.0):
    try:
        v=r.get(key,default)
        return default if pd.isna(v) else float(v)
    except Exception:return float(default)

def _v858_player_archetype(r):
    """Explainable archetypes using role/usage fields when available, with conservative fallbacks."""
    pos=str(r.get("position","") or "").upper()
    proj=max(.1,_v859_num(r,"projection",0)); recent=_v859_num(r,"_recent_ppg3",proj)
    targets=_v859_num(r,"_targets_last",0); carries=_v859_num(r,"_carries_last",0)
    touches=_v859_num(r,"_touches_last",targets+carries); snap=_v859_num(r,"_snap_pct_last",0); route=_v859_num(r,"_route_pct_last",0); rz=_v859_num(r,"_rz_opp_last",0)
    if snap>1.5:snap/=100.0
    if route>1.5:route/=100.0
    if pos=="RB":
        if targets>=4 or (touches>0 and targets/max(1,touches)>=.28): return "Receiving RB"
        if carries>=15 or touches>=18 or snap>=.70:return "Workhorse RB"
        if rz>=3:return "Goal-line / TD RB"
        return "Committee RB"
    if pos=="WR":
        if targets>=8 or route>=.85:return "Volume WR"
        if recent>proj*1.20:return "Boom / Deep-threat WR"
        if route>=.65:return "Every-down WR"
        return "Rotational / Upside WR"
    if pos=="QB":
        rush=_v859_num(r,"rushing_yards",0)+_v859_num(r,"_rush_yards_last",0)
        return "Mobile QB" if rush>=25 or recent>proj*1.18 else "Pocket QB"
    if pos=="TE":
        if targets>=6 or route>=.75:return "Target-heavy TE"
        if rz>=2:return "TD / Red-zone TE"
        return "Standard TE"
    if pos=="DL":return "EDGE / Impact DL" if recent>=proj else "Interior / Standard DL"
    if pos=="DB":return "Box / Playmaking DB" if recent>=proj else "Coverage / Standard DB"
    if pos=="K":return "Kicker"
    return pos or "UNKNOWN"

def _v859_native_call(c):
    if bool((c or {}).get("native_instrumentation")):
        return True
    # Version-forward fallback: any instrumented model snapshot from V8.58+ counts as native.
    # Avoid hard-coded release lists so future versions do not silently become "legacy".
    v=str((c or {}).get("model_version","") or "").upper()
    m=re.search(r"V?(\d+)\.(\d+)",v)
    if not m:
        return False
    return (int(m.group(1)),int(m.group(2))) >= (8,58)





def _v862_player_team_lookup():
    """Conservative player->team lookup for descriptive evidence breadth.

    Prefer the live active-roster directory already loaded by the app, then the current board,
    then any disk board that actually carries team identity. This never changes a prediction;
    it only prevents valid graded evidence from losing team metadata downstream.
    """
    out={}
    def _add_frame(df):
        if not isinstance(df,pd.DataFrame) or df.empty:return
        pcol=next((c for c in ["player","Player","name","Name"] if c in df.columns),None)
        tcol=next((c for c in ["team","Team","nfl_team","NFL Team"] if c in df.columns),None)
        if not pcol or not tcol:return
        for _,r in df[[pcol,tcol]].dropna().iterrows():
            k=_owner_key(r[pcol]); t=str(r[tcol] or "").strip().upper()
            if k and t and t not in {"FA","NAN","NONE","UNKNOWN","—"}:out.setdefault(k,t)
    try:_add_frame(globals().get("_active_roster_export"))
    except Exception:pass
    try:_add_frame(globals().get("board"))
    except Exception:pass
    for fn in ("production_board.csv","fallback_ppr_top300_2026.csv"):
        try:_add_frame(pd.read_csv(fn))
        except Exception:pass
    return out

def _v862_historical_context(c):
    """Backfill descriptive team/matchup context without converting a historical row to native evidence."""
    team=str(c.get("starter_team",c.get("team","")) or "").strip().upper()
    team_source="FROZEN" if team else ""
    if not team:
        team=_v862_player_team_lookup().get(_owner_key(c.get("starter",c.get("player",""))),"")
        if team: team_source="BACKFILLED CURRENT ROSTER"
    band=str(c.get("matchup_band","") or "").strip().upper()
    band_source="FROZEN" if band else ""
    if not band:
        adj=_v859_num(c,"matchup_adjustment",_v859_num(c,"_matchup_adjustment",0))
        band="FAVORABLE" if adj>0.35 else "TOUGH" if adj<-0.35 else "NEUTRAL"
        band_source="BACKFILLED FROM FROZEN ADJUSTMENT"
    return {"team":team,"team_source":team_source or "UNKNOWN","matchup_band":band,"matchup_source":band_source or "UNKNOWN"}

def _v863_capture_preflight(snapshot=None):
    """Strict pre-save validator with per-player diagnostics. Never mutates the candidate snapshot."""
    audit=_v861_capture_audit(snapshot)
    rows=[]
    if isinstance(snapshot,dict):
        for c in snapshot.get("start_sit",[]) or []:
            missing=[]
            for f in _v861_capture_required_fields(snapshot,current=True):
                v=c.get(f)
                if f=="native_instrumentation": ok=(v is True)
                elif f=="feature_attribution": ok=isinstance(v,dict) and all(k in v for k in ["baseline","matchup","role","recent_form"])
                elif f=="source_ages": ok=isinstance(v,dict) and bool(v.get("captured_at_utc"))
                elif f=="freshness_confidence": ok=isinstance(v,dict) and v.get("score") is not None and bool(v.get("grade"))
                elif f=="game_lock_utc": ok=(_v865_parse_utc(v) is not None)
                else: ok=v is not None and str(v).strip()!=""
                if not ok: missing.append(f)
            rows.append({"Player":c.get("starter","Unknown"),"Status":"READY" if not missing else "MISSING","Missing fields":"—" if not missing else ", ".join(missing)})
    return {**audit,"rows":pd.DataFrame(rows)}

def _v863_sample_quality_penalties(history,state_snapshot):
    d=_v860_sample_breakdown(history,state_snapshot).copy()
    if d.empty:return d
    d["Gap %"]=(100-pd.to_numeric(d["Completion %"],errors="coerce").fillna(0)).clip(lower=0)
    d["Impact"]=(d["Gap %"]*1.0).round(0)
    d=d.sort_values(["Gap %","Dimension"],ascending=[False,True])
    return d

