            try:
                _v791_cov["weekly_projection_matches"]=int(pd.to_numeric(board.get("_external_week_projection",pd.Series(index=board.index,dtype=float)),errors="coerce").notna().sum())
            except Exception:
                pass
            _v791_meta["coverage"]=_v791_cov
            _v871_fetch_mark_success(state,"board",mode="FETCH",rows=len(board),detail="canonical weekly board persisted")
            _v791_meta["source_fetch_ledger"]=dict(state.get("_source_fetch_ledger",{}) or {})
            state["_weekly_board_snapshot_meta"]=_v791_meta
            # Keep this run's fast-navigation globals synchronized with the final save.
            _v778_snapshot_blob=""
            _v778_snapshot_board=board.copy()
            _v778_snapshot_meta=dict(_v791_meta)
            _v778_snapshot_loaded=True
            # V8.73: finalize one transaction receipt only after the canonical board
