                _moves_df["Transaction Score"]=(pd.to_numeric(_moves_df["Transaction Score"],errors="coerce").fillna(0) + pd.to_numeric(_moves_df["6W Delta"],errors="coerce").fillna(0)*0.65 + (pd.to_numeric(_moves_df["Replacement Probability"],errors="coerce").fillna(.5)-.5)*3.0 + pd.to_numeric(_moves_df["Playoff Edge"],errors="coerce").fillna(0)*2.0).round(2)
